@_source_base.dataclass
class AxisTransform:
    """Image-centred rotation from source X/Y into lateral/longitudinal axes."""
    angle_from_vertical_deg: float
    origin_x_um: float
    origin_y_um: float
    source: str
    confidence: str
    candidate_count: int
    angular_mad_deg: float | None
    warning: str

    @property
    def radians(self) -> float:
        return _source_base.math.radians(self.angle_from_vertical_deg)

    def forward(self, x_um: float, y_um: float) -> tuple[float, float]:
        """Return lateral and longitudinal coordinates in micrometres."""
        x = x_um - self.origin_x_um
        y = y_um - self.origin_y_um
        sine = _source_base.math.sin(self.radians)
        cosine = _source_base.math.cos(self.radians)
        lateral = cosine * x - sine * y
        longitudinal = sine * x + cosine * y
        return (lateral, longitudinal)

    def inverse(self, lateral_um: float, longitudinal_um: float) -> tuple[float, float]:
        """Map rotated coordinates back to source X/Y micrometres."""
        sine = _source_base.math.sin(self.radians)
        cosine = _source_base.math.cos(self.radians)
        x = cosine * lateral_um + sine * longitudinal_um + self.origin_x_um
        y = -sine * lateral_um + cosine * longitudinal_um + self.origin_y_um
        return (x, y)
_source_base.AxisTransform = AxisTransform

def utc_now() -> str:
    return _source_base.datetime.now(_source_base.timezone.utc).isoformat()
_source_base.utc_now = utc_now

def sha256_file(path: _source_base.Path, chunk_size: int=1024 * 1024) -> str:
    digest = _source_base.hashlib.sha256()
    with path.open('rb') as handle:
        while True:
            chunk = handle.read(chunk_size)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()
_source_base.sha256_file = sha256_file

def parse_bool(value: _source_base.Any, default: bool=False) -> bool:
    if isinstance(value, bool):
        return value
    if value is None or str(value).strip() == '':
        return default
    text = str(value).strip().lower()
    if text in {'true', '1', 'yes', 'y'}:
        return True
    if text in {'false', '0', 'no', 'n'}:
        return False
    raise ValueError(f'Cannot interpret Boolean value: {value!r}')
_source_base.parse_bool = parse_bool

def optional_float(value: _source_base.Any) -> float | None:
    if value is None or str(value).strip() == '':
        return None
    number = float(value)
    return number if _source_base.math.isfinite(number) else None
_source_base.optional_float = optional_float

def optional_int(value: _source_base.Any) -> int | None:
    number = _source_base.optional_float(value)
    return None if number is None else int(round(number))
_source_base.optional_int = optional_int

def safe_divide(numerator: float | None, denominator: float | None) -> float | None:
    if numerator is None or denominator is None or denominator == 0:
        return None
    value = numerator / denominator
    return value if _source_base.math.isfinite(value) else None
_source_base.safe_divide = safe_divide

def finite_values(values: _source_base.Iterable[_source_base.Any]) -> _source_base.np.ndarray:
    cleaned: list[float] = []
    for value in values:
        number = _source_base.optional_float(value)
        if number is not None:
            cleaned.append(number)
    return _source_base.np.asarray(cleaned, dtype=float)
_source_base.finite_values = finite_values

def sample_summary(values: _source_base.Iterable[_source_base.Any], prefix: str) -> dict[str, _source_base.Any]:
    array = _source_base.finite_values(values)
    result: dict[str, _source_base.Any] = {f'{prefix}_n': int(array.size)}
    if array.size == 0:
        for suffix in ('mean', 'median', 'sd', 'cv_percent', 'se', 'ci95_low', 'ci95_high', 'min', 'max'):
            result[f'{prefix}_{suffix}'] = None
        return result
    mean = float(_source_base.np.mean(array))
    median = float(_source_base.np.median(array))
    minimum = float(_source_base.np.min(array))
    maximum = float(_source_base.np.max(array))
    if array.size >= 2:
        sd = float(_source_base.np.std(array, ddof=1))
        se = sd / _source_base.math.sqrt(array.size)
        ci_low = mean - 1.96 * se
        ci_high = mean + 1.96 * se
    else:
        sd = se = ci_low = ci_high = None
    result.update({f'{prefix}_mean': mean, f'{prefix}_median': median, f'{prefix}_sd': sd, f'{prefix}_cv_percent': 100.0 * sd / abs(mean) if sd is not None and (not _source_base.math.isclose(mean, 0.0)) else None, f'{prefix}_se': se, f'{prefix}_ci95_low': ci_low, f'{prefix}_ci95_high': ci_high, f'{prefix}_min': minimum, f'{prefix}_max': maximum})
    return result
_source_base.sample_summary = sample_summary

def relative_asymmetry(first: float | None, second: float | None) -> float | None:
    """Return 2*absolute difference/sum; zero means a perfectly equal pair."""
    if first is None or second is None or first + second <= 0:
        return None
    return 2.0 * abs(first - second) / (first + second)
_source_base.relative_asymmetry = relative_asymmetry

def axial_angle_difference(first_deg: float | None, second_deg: float | None) -> float | None:
    """Smallest difference between unoriented axes, in degrees."""
    if first_deg is None or second_deg is None:
        return None
    difference = abs(first_deg - second_deg) % 180.0
    return min(difference, 180.0 - difference)
_source_base.axial_angle_difference = axial_angle_difference

def normalize_axial_angle(angle_deg: float) -> float:
    """Normalize an unoriented line angle to [-90, 90)."""
    return (angle_deg + 90.0) % 180.0 - 90.0
_source_base.normalize_axial_angle = normalize_axial_angle

def json_safe(value: _source_base.Any) -> _source_base.Any:
    if isinstance(value, _source_base.Path):
        return str(value)
    if isinstance(value, _source_base.np.generic):
        return value.item()
    if isinstance(value, _source_base.np.ndarray):
        return value.tolist()
    if isinstance(value, dict):
        return {str(key): _source_base.json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_source_base.json_safe(item) for item in value]
    if isinstance(value, float) and (not _source_base.math.isfinite(value)):
        return None
    return value
_source_base.json_safe = json_safe

def csv_value(value: _source_base.Any) -> _source_base.Any:
    if value is None:
        return ''
    if isinstance(value, float) and (not _source_base.math.isfinite(value)):
        return ''
    if isinstance(value, (list, tuple, dict)):
        return _source_base.json.dumps(_source_base.json_safe(value), sort_keys=True)
    return value
_source_base.csv_value = csv_value

def ordered_fieldnames(rows: _source_base.Sequence[dict[str, _source_base.Any]]) -> list[str]:
    fields: list[str] = []
    seen: set[str] = set()
    for row in rows:
        for field in row:
            if field not in seen:
                seen.add(field)
                fields.append(field)
    return fields
_source_base.ordered_fieldnames = ordered_fieldnames

def write_csv(path: _source_base.Path, rows: _source_base.Sequence[dict[str, _source_base.Any]], empty_table_fields: _source_base.Sequence[str] | None=None) -> None:
    fields = _source_base.ordered_fieldnames(rows)
    if not fields and empty_table_fields:
        fields = list(empty_table_fields)
    if not fields:
        raise ValueError(f'Cannot write a table with no columns: {path}')
    with path.open('w', newline='', encoding='utf-8') as handle:
        writer = _source_base.csv.DictWriter(handle, fieldnames=fields, extrasaction='ignore')
        writer.writeheader()
        for row in rows:
            writer.writerow({field: _source_base.csv_value(row.get(field)) for field in fields})
_source_base.write_csv = write_csv

def read_csv(path: _source_base.Path) -> list[dict[str, str]]:
    if not path.is_file():
        raise FileNotFoundError(path)
    with path.open('r', newline='', encoding='utf-8-sig') as handle:
        return list(_source_base.csv.DictReader(handle))
_source_base.read_csv = read_csv

def group_by(rows: _source_base.Iterable[dict[str, _source_base.Any]], key: str) -> dict[str, list[dict[str, _source_base.Any]]]:
    grouped: dict[str, list[dict[str, _source_base.Any]]] = _source_base.defaultdict(list)
    for row in rows:
        grouped[str(row[key])].append(row)
    return dict(grouped)
_source_base.group_by = group_by

def require_fields(rows: _source_base.Sequence[dict[str, _source_base.Any]], fields: _source_base.Sequence[str], label: str) -> None:
    if not rows:
        raise ValueError(f'{label} contains no data rows.')
    missing = [field for field in fields if field not in rows[0]]
    if missing:
        raise ValueError(f'{label} is missing required fields: {missing}')
_source_base.require_fields = require_fields

def load_audited_row_count_overrides(path: _source_base.Path | None, valid_image_names: set[str], maximum_rows_per_band: int) -> tuple[dict[tuple[str, str], int], dict[str, _source_base.Any]]:
    """Load optional, explicit band-level row counts without changing source data.

    An override is appropriate only after visual biological audit shows that
    center coordinates alone cannot distinguish the rows reliably. The exact
    source-image name is required so an override can never leak across images.
    """
    if path is None:
        return ({}, {'available': False, 'path': None, 'sha256': None, 'override_count': 0})
    resolved = path.expanduser().resolve()
    rows = _source_base.read_csv(resolved)
    _source_base.require_fields(rows, ('source_image_name', 'band_id', 'row_count'), str(resolved))
    overrides: dict[tuple[str, str], int] = {}
    for line_number, row in enumerate(rows, start=2):
        image_name = str(row.get('source_image_name', '')).strip()
        band_id = str(row.get('band_id', '')).strip().upper()
        raw_row_count = _source_base.optional_float(row.get('row_count'))
        row_count = int(round(raw_row_count)) if raw_row_count is not None and _source_base.math.isclose(raw_row_count, round(raw_row_count)) else None
        if image_name not in valid_image_names:
            raise ValueError(f'Unknown source_image_name on line {line_number} of {resolved}: {image_name!r}')
        if not (len(band_id) == 4 and band_id.startswith('B') and band_id[1:].isdigit()):
            raise ValueError(f'Invalid band_id on line {line_number} of {resolved}: {band_id!r}; expected B001-style identifiers.')
        if row_count is None or not 1 <= row_count <= maximum_rows_per_band:
            raise ValueError(f"Invalid row_count on line {line_number} of {resolved}: {row.get('row_count')!r}; expected 1..{maximum_rows_per_band}.")
        key = (image_name, band_id)
        if key in overrides:
            raise ValueError(f'Duplicate audited row-count override for {image_name}, {band_id} in {resolved}.')
        overrides[key] = row_count
    return (overrides, {'available': True, 'path': str(resolved), 'sha256': _source_base.sha256_file(resolved), 'override_count': len(overrides)})
_source_base.load_audited_row_count_overrides = load_audited_row_count_overrides

