    parser.add_argument('--row-model-min-delta-bic', type=float, default=6.0)
    parser.add_argument('--row-model-min-rss-reduction', type=float, default=0.2)
    parser.add_argument('--row-model-additional-row-min-delta-bic', type=float, default=10.0)
    parser.add_argument('--row-model-residual-floor-width-factor', type=float, default=0.05)
    parser.add_argument('--row-model-simple-fit-stop-width-factor', type=float, default=0.05)
    parser.add_argument('--two-row-rescue-min-rss-reduction', type=float, default=0.45)
