_source_base.BAND_COLORS_BGR = ((60, 180, 75), (255, 130, 40), (70, 70, 230), (190, 80, 180), (30, 200, 220), (210, 170, 50), (140, 90, 230), (80, 190, 190))

def make_spatial_audit_overlay(input_dir: _source_base.Path, output_path: _source_base.Path, image_metadata: dict[str, _source_base.Any], stoma_traits: list[dict[str, _source_base.Any]], row_records: list[dict[str, _source_base.Any]], band_records: list[dict[str, _source_base.Any]], axis: _source_base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    overview_relative = str(image_metadata.get('indexed_overview_path', '')).strip()
    overview_path = input_dir / overview_relative if overview_relative else None
    image = _source_base.cv2.imread(str(overview_path), _source_base.cv2.IMREAD_COLOR) if overview_path and overview_path.is_file() else None
    if image is None:
        height = _source_base.optional_int(image_metadata.get('image_height'))
        width = _source_base.optional_int(image_metadata.get('image_width'))
        if height is None or width is None:
            raise ValueError('Cannot create audit overlay without image dimensions.')
        image = _source_base.np.full((height, width, 3), 235, dtype=_source_base.np.uint8)
    band_color = {band['band_id']: _source_base.BAND_COLORS_BGR[(index - 1) % len(_source_base.BAND_COLORS_BGR)] for index, band in enumerate(band_records, start=1)}
    corners_um = [axis.forward(x, y) for x, y in ((0.0, 0.0), (image.shape[1] / px_per_um_x, 0.0), (0.0, image.shape[0] / px_per_um_y), (image.shape[1] / px_per_um_x, image.shape[0] / px_per_um_y))]
    long_min = min((value[1] for value in corners_um))
    long_max = max((value[1] for value in corners_um))
    for row in row_records:
        long_values = _source_base.np.linspace(long_min, long_max, 120)
        points: list[tuple[int, int]] = []
        for longitudinal in long_values:
            lateral = _source_base.row_lateral_at(row, float(longitudinal))
            x_um, y_um = axis.inverse(lateral, float(longitudinal))
            x = int(round(x_um * px_per_um_x))
            y = int(round(y_um * px_per_um_y))
            if -50 <= x <= image.shape[1] + 50 and -50 <= y <= image.shape[0] + 50:
                points.append((x, y))
        if len(points) >= 2:
            _source_base.cv2.polylines(image, [_source_base.np.asarray(points, dtype=_source_base.np.int32).reshape(-1, 1, 2)], False, band_color[row['band_id']], 2, _source_base.cv2.LINE_AA)
    for row in stoma_traits:
        x = int(round(row['center_x_pixels']))
        y = int(round(row['center_y_pixels']))
        color = band_color.get(row.get('band_id'), (160, 160, 160))
        _source_base.cv2.circle(image, (x, y), 5, color, -1, _source_base.cv2.LINE_AA)
        label = f"{row.get('band_id', '?')}/{row.get('row_id', '?')}"
        _source_base.cv2.putText(image, label, (x + 5, y + 12), _source_base.cv2.FONT_HERSHEY_SIMPLEX, 0.3, (0, 0, 0), 2, _source_base.cv2.LINE_AA)
        _source_base.cv2.putText(image, label, (x + 5, y + 12), _source_base.cv2.FONT_HERSHEY_SIMPLEX, 0.3, color, 1, _source_base.cv2.LINE_AA)
    origin = (80, image.shape[0] - 80)
    arrow_length = 120
    angle = axis.radians
    endpoint = (int(round(origin[0] - arrow_length * _source_base.math.sin(angle))), int(round(origin[1] - arrow_length * _source_base.math.cos(angle))))
    _source_base.cv2.arrowedLine(image, origin, endpoint, (255, 255, 255), 5, _source_base.cv2.LINE_AA, tipLength=0.15)
    _source_base.cv2.arrowedLine(image, origin, endpoint, (0, 0, 0), 2, _source_base.cv2.LINE_AA, tipLength=0.15)
    _source_base.cv2.putText(image, 'longitudinal axis', (15, image.shape[0] - 25), _source_base.cv2.FONT_HERSHEY_SIMPLEX, 0.55, (0, 0, 0), 2, _source_base.cv2.LINE_AA)
    success = _source_base.cv2.imwrite(str(output_path), image, [_source_base.cv2.IMWRITE_PNG_COMPRESSION, 6])
    if not success:
        raise RuntimeError(f'Failed to write audit overlay: {output_path}')
_source_base.make_spatial_audit_overlay = make_spatial_audit_overlay

def prepare_stoma_base_rows(stoma_source_rows: list[dict[str, _source_base.Any]], image_metadata: dict[str, _source_base.Any], px_per_um_x: float, px_per_um_y: float, morphometry: dict[str, dict[str, _source_base.Any]]) -> list[dict[str, _source_base.Any]]:
    base: list[dict[str, _source_base.Any]] = []
    for source in stoma_source_rows:
        x_pixels = float(source['prediction_center_x_pixels'])
        y_pixels = float(source['prediction_center_y_pixels'])
        row = {'source_image_name': source['source_image_name'], 'surface': source['surface'], 'slide_id': source.get('slide_id', image_metadata.get('slide_id', '')), 'plant_replicate': source.get('plant_replicate', image_metadata.get('plant_replicate', '')), 'biological_unit': source.get('biological_unit', image_metadata.get('biological_unit', '')), 'stoma_id': source['stoma_id'], 'stoma_number': _source_base.optional_int(source.get('stoma_number')), 'detector_confidence': _source_base.optional_float(source.get('detector_confidence')), 'center_x_pixels': x_pixels, 'center_y_pixels': y_pixels, 'center_x_um': x_pixels / px_per_um_x, 'center_y_um': y_pixels / px_per_um_y, 'pixels_per_um_x': px_per_um_x, 'pixels_per_um_y': px_per_um_y, 'prediction_x1_pixels': _source_base.optional_float(source.get('prediction_x1_pixels')), 'prediction_y1_pixels': _source_base.optional_float(source.get('prediction_y1_pixels')), 'prediction_x2_pixels': _source_base.optional_float(source.get('prediction_x2_pixels')), 'prediction_y2_pixels': _source_base.optional_float(source.get('prediction_y2_pixels')), 'prediction_width_um': _source_base.safe_divide(_source_base.optional_float(source.get('prediction_width_pixels')) or float(source['prediction_x2_pixels']) - float(source['prediction_x1_pixels']), px_per_um_x), 'prediction_height_um': _source_base.safe_divide(_source_base.optional_float(source.get('prediction_height_pixels')) or float(source['prediction_y2_pixels']) - float(source['prediction_y1_pixels']), px_per_um_y), 'density_eligible': True, 'classifier_predicted_label': source.get('classifier_predicted_label', ''), 'probability_full_good': _source_base.optional_float(source.get('probability_full_good')), 'probability_guard_only': _source_base.optional_float(source.get('probability_guard_only')), 'probability_bad': _source_base.optional_float(source.get('probability_bad')), 'segmentation_route': source.get('segmentation_route', ''), 'post_segmentation_top_up': _source_base.parse_bool(source.get('post_segmentation_top_up')), 'segmentation_evidence_tier': source.get('segmentation_evidence_tier', ''), 'edge_clipped_crop': _source_base.parse_bool(source.get('edge_clipped')), 'other_detection_center_in_crop': _source_base.parse_bool(source.get('other_detection_center_in_crop')), 'mask_archive_path': source.get('mask_archive_path', '')}
        row.update(morphometry.get(source['stoma_id'], {}))
        base.append(row)
    return base
_source_base.prepare_stoma_base_rows = prepare_stoma_base_rows

def process_image(input_dir: _source_base.Path, staging_dir: _source_base.Path, image_metadata: dict[str, _source_base.Any], stoma_source_rows: list[dict[str, _source_base.Any]], hair_rows: list[dict[str, _source_base.Any]] | None, settings: _source_base.TraitSettings, audited_row_counts: dict[str, int], create_overlay: bool) -> tuple[list[dict[str, _source_base.Any]], dict[str, _source_base.Any], list[dict[str, _source_base.Any]], list[dict[str, _source_base.Any]], list[dict[str, _source_base.Any]], dict[str, _source_base.Any]]:
    px_per_um_x = _source_base.optional_float(image_metadata.get('metadata_pixels_per_um_x'))
    px_per_um_y = _source_base.optional_float(image_metadata.get('metadata_pixels_per_um_y'))
    width_pixels = _source_base.optional_int(image_metadata.get('image_width'))
    height_pixels = _source_base.optional_int(image_metadata.get('image_height'))
    if not _source_base.parse_bool(image_metadata.get('calibrated_traits_permitted')):
        raise ValueError(f"Calibrated traits are not permitted for {image_metadata['source_image_name']}: {image_metadata.get('calibration_status')}")
    if px_per_um_x is None or px_per_um_y is None or width_pixels is None or (height_pixels is None):
        raise ValueError(f"Missing calibration or dimensions for {image_metadata['source_image_name']}")
    width_um = width_pixels / px_per_um_x
    height_um = height_pixels / px_per_um_y
    morphometry, cell_rows = _source_base.extract_image_morphometry(input_dir, stoma_source_rows, px_per_um_x, px_per_um_y)
    stoma_traits = _source_base.prepare_stoma_base_rows(stoma_source_rows, image_metadata, px_per_um_x, px_per_um_y, morphometry)
    axis = _source_base.estimate_vertical_axis(stoma_traits, morphometry, width_um, height_um, settings)
    for row in stoma_traits:
        lateral, longitudinal = axis.forward(row['center_x_um'], row['center_y_um'])
        row['lateral_coordinate_um'] = lateral
        row['longitudinal_coordinate_um'] = longitudinal
        row['longitudinal_axis_angle_from_vertical_deg'] = axis.angle_from_vertical_deg
        orientation_keys = [key for key in row if key.endswith('_orientation_from_vertical_deg')]
        for key in orientation_keys:
            orientation = _source_base.optional_float(row.get(key))
            relative_key = key.replace('_orientation_from_vertical_deg', '_orientation_relative_leaf_axis_deg')
            row[relative_key] = _source_base.normalize_axial_angle(orientation - axis.angle_from_vertical_deg) if orientation is not None else None
    for cell in cell_rows:
        orientation = _source_base.optional_float(cell.get('orientation_from_vertical_deg'))
        cell['orientation_relative_leaf_axis_deg'] = _source_base.normalize_axial_angle(orientation - axis.angle_from_vertical_deg) if orientation is not None else None
    row_records, band_records, assignments, row_band_audit = _source_base.infer_rows_and_bands(stoma_traits, settings, audited_row_counts=audited_row_counts)
    for row in row_records:
        row['source_image_name'] = image_metadata['source_image_name']
        row['surface'] = image_metadata['surface']
    for band in band_records:
        band['source_image_name'] = image_metadata['source_image_name']
        band['surface'] = image_metadata['surface']
    _source_base.add_row_neighbors(stoma_traits, row_records, assignments)
    spatial_probability = _source_base.add_general_nearest_neighbors(stoma_traits, hair_rows, width_um, height_um, settings)
    _source_base.add_size_normalized_spacing(stoma_traits)
    image_traits = _source_base.image_trait_summary(image_metadata, stoma_traits, hair_rows, row_records, band_records, axis, spatial_probability, row_band_audit, width_um, height_um)
    if create_overlay:
        safe_name = _source_base.Path(str(image_metadata['source_image_name'])).name
        for suffix in ('.ome.tiff', '.ome.tif', '.tiff', '.tif'):
            if safe_name.lower().endswith(suffix):
                safe_name = safe_name[:-len(suffix)]
                break
        overlay_relative = f'spatial_audit_overlays/{safe_name}_row_band_audit.png'
        _source_base.make_spatial_audit_overlay(input_dir, staging_dir / overlay_relative, image_metadata, stoma_traits, row_records, band_records, axis, px_per_um_x, px_per_um_y)
        image_traits['spatial_audit_overlay_path'] = overlay_relative
    else:
        image_traits['spatial_audit_overlay_path'] = ''
    for row in row_records:
        row.pop('_point_indices', None)
    for band in band_records:
        band.pop('_point_indices', None)
    return (stoma_traits, image_traits, cell_rows, row_records, band_records, row_band_audit)
_source_base.process_image = process_image

def run_trait_extraction() -> _source_base.Path:
    args = _source_base.parse_arguments()
    settings = _source_base.build_settings(args)
    input_dir, output_dir, staging_dir = _source_base.validate_paths(args)
    input_rows = _source_base.read_csv(input_dir / 'input_image_manifest.csv')
    stoma_rows = _source_base.read_csv(input_dir / 'stoma_segmentation_manifest.csv')
    image_pipeline_rows = _source_base.read_csv(input_dir / 'image_pipeline_summary.csv')
    selected_mask_rows = _source_base.read_csv(input_dir / 'selected_mask_instances.csv')
    hair_path = input_dir / 'hair_cell_detection_manifest.csv'
    hair_rows = _source_base.read_csv(hair_path) if hair_path.is_file() else None
    _source_base.require_fields(input_rows, ('source_image_name', 'source_image_path', 'surface', 'image_width', 'image_height', 'metadata_pixels_per_um_x', 'metadata_pixels_per_um_y', 'calibrated_traits_permitted'), 'input_image_manifest.csv')
