    partition_gap_ratio: float | None = None
    partition_gap_width_factor: float | None = None
    partition_left_alternation: float | None = None
    partition_right_alternation: float | None = None
    labels = _source_v14.np.asarray(candidate['labels'], dtype=int)
    candidate_points = list(candidate['point_indices'])

    def candidate_alternation(first_group: int, last_group: int) -> float | None:
        local_positions = [position for position, label in enumerate(labels) if first_group <= int(label) < last_group]
        if len(local_positions) < 2 or last_group - first_group < 2:
            return None
        if _source_v14._ACTIVE_LONGITUDINAL_COORDINATES is not None:
            local_positions.sort(key=lambda position: _source_v14._ACTIVE_LONGITUDINAL_COORDINATES[candidate_points[position]])
        sequence = [int(labels[position]) for position in local_positions]
        return sum((first != second for first, second in zip(sequence[:-1], sequence[1:]))) / (len(sequence) - 1)
    if int(candidate['k']) >= 2 * settings.band_partition_min_rows_per_side:
        for split in range(settings.band_partition_min_rows_per_side, int(candidate['k']) - settings.band_partition_min_rows_per_side + 1):
            boundary_gap = float(gaps[split - 1])
