def _direct_two_row_structural_evidence(candidate: dict[str, _source_v14.Any]) -> dict[str, _source_v14.Any]:
    """Describe whether a fitted two-row model has biological stagger structure."""
    labels = _source_v14.np.asarray(candidate['labels'], dtype=int)
    point_indices = list(candidate['point_indices'])
    evidence: dict[str, _source_v14.Any] = {'direct_two_row_alternation': None, 'direct_two_row_phase_offset_normalized': None, 'direct_two_row_longest_alternating_sequence': None}
    if int(candidate['k']) != 2 or len(labels) < 2 or _source_v14._ACTIVE_LONGITUDINAL_COORDINATES is None:
        return evidence
    longitudinal = _source_v14.np.asarray([_source_v14._ACTIVE_LONGITUDINAL_COORDINATES[index] for index in point_indices], dtype=float)
    order = _source_v14.np.argsort(longitudinal, kind='stable')
    sequence = labels[order].tolist()
    evidence['direct_two_row_alternation'] = float(sum((first != second for first, second in zip(sequence[:-1], sequence[1:]))) / (len(sequence) - 1))
    longest = current = 1
    for first, second in zip(sequence[:-1], sequence[1:]):
        current = current + 1 if first != second else 1
        longest = max(longest, current)
    evidence['direct_two_row_longest_alternating_sequence'] = int(longest)
    row_coordinates = [_source_v14.np.sort(longitudinal[labels == group]) for group in (0, 1)]
    pooled_within_row_gaps = _source_v14.np.concatenate([_source_v14.np.diff(values) for values in row_coordinates if len(values) >= 2]) if any((len(values) >= 2 for values in row_coordinates)) else _source_v14.np.asarray([])
    if len(pooled_within_row_gaps) and len(row_coordinates[0]) and len(row_coordinates[1]):
        typical_spacing = float(_source_v14.np.median(pooled_within_row_gaps))
        if typical_spacing > 0:
            first, second = row_coordinates
            offsets = [float(_source_v14.np.min(_source_v14.np.abs(second - value))) for value in first]
            offsets.extend((float(_source_v14.np.min(_source_v14.np.abs(first - value))) for value in second))
            evidence['direct_two_row_phase_offset_normalized'] = float(_source_v14.np.median(offsets) / typical_spacing)
    return evidence
_source_v14._direct_two_row_structural_evidence = _direct_two_row_structural_evidence

