def _row_group_alternation(rows: list[dict[str, _source_v14.Any]], stoma_traits: list[dict[str, _source_v14.Any]]) -> float | None:
    """Fraction of successive longitudinal observations that switch rows."""
    observations = sorted(((float(stoma_traits[index]['longitudinal_coordinate_um']), row['row_id']) for row in rows for index in row['_point_indices']), key=lambda item: item[0])
