            x_um, y_um = axis.inverse(lateral_um + float(offset), float(longitudinal_um))
            x = int(round(x_um * px_x))
            y = int(round(y_um * px_y))
            if 0 <= x < width and 0 <= y < height:
                local.append(float(_source_v14._ACTIVE_HORIZONTAL_GRADIENT[y, x]))
