def _accessible_longitudinal_span_um(lateral_um: float, stoma_traits: list[dict[str, _source_v14.Any]]) -> float | None:
    """Approximate the visible length of a band-centre line inside the image."""
    if _source_v14._ACTIVE_IMAGE_METADATA is None:
        return None
    axis = _source_v14._active_axis(stoma_traits)
    if axis is None:
        return None
    px_x = _source_v14.base.optional_float(_source_v14._ACTIVE_IMAGE_METADATA.get('metadata_pixels_per_um_x'))
    px_y = _source_v14.base.optional_float(_source_v14._ACTIVE_IMAGE_METADATA.get('metadata_pixels_per_um_y'))
    width = _source_v14.base.optional_int(_source_v14._ACTIVE_IMAGE_METADATA.get('image_width'))
    height = _source_v14.base.optional_int(_source_v14._ACTIVE_IMAGE_METADATA.get('image_height'))
    if px_x is None or px_y is None or width is None or (height is None):
        return None
    corners = [axis.forward(x, y) for x, y in ((0.0, 0.0), (width / px_x, 0.0), (0.0, height / px_y), (width / px_x, height / px_y))]
    candidates = _source_v14.np.linspace(min((value[1] for value in corners)), max((value[1] for value in corners)), 1200)
    visible: list[float] = []
    for longitudinal_um in candidates:
        x_um, y_um = axis.inverse(lateral_um, float(longitudinal_um))
        if 0.0 <= x_um <= width / px_x and 0.0 <= y_um <= height / px_y:
            visible.append(float(longitudinal_um))
    return float(max(visible) - min(visible)) if len(visible) >= 2 else None
