def make_spatial_audit_overlay_v14(input_dir: _source_v14.Path, output_path: _source_v14.Path, image_metadata: dict[str, _source_v14.Any], stoma_traits: list[dict[str, _source_v14.Any]], row_records: list[dict[str, _source_v14.Any]], band_records: list[dict[str, _source_v14.Any]], axis: _source_v14.base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    """Draw the normal overlay, then visibly mark spatially excluded bands."""
    _source_v14._BASE_MAKE_SPATIAL_AUDIT_OVERLAY(input_dir, output_path, image_metadata, stoma_traits, row_records, band_records, axis, px_per_um_x, px_per_um_y)
    excluded = [band for band in band_records if not bool(band.get('band_spatial_eligible'))]
    if not excluded:
        return
    image = _source_v14.base.cv2.imread(str(output_path), _source_v14.base.cv2.IMREAD_COLOR)
    if image is None:
        return
    for band in excluded:
        for index in band['_point_indices']:
            x = int(round(stoma_traits[index]['center_x_pixels']))
            y = int(round(stoma_traits[index]['center_y_pixels']))
            _source_v14.base.cv2.line(image, (x - 11, y - 11), (x + 11, y + 11), (0, 0, 255), 3)
            _source_v14.base.cv2.line(image, (x - 11, y + 11), (x + 11, y - 11), (0, 0, 255), 3)
        members = band['_point_indices']
        if members:
            x = int(round(_source_v14.np.mean([stoma_traits[index]['center_x_pixels'] for index in members])))
            y = max(24, int(round(min((stoma_traits[index]['center_y_pixels'] for index in members)))) - 12)
            _source_v14.base.cv2.putText(image, f"{band['band_id']} EXCLUDED: partial field", (max(5, x - 110), y), _source_v14.base.cv2.FONT_HERSHEY_SIMPLEX, 0.48, (0, 0, 255), 2, _source_v14.base.cv2.LINE_AA)
    if not _source_v14.base.cv2.imwrite(str(output_path), image, [_source_v14.base.cv2.IMWRITE_PNG_COMPRESSION, 6]):
        raise RuntimeError(f'Failed to update v1.4 audit overlay: {output_path}')
_source_v14.make_spatial_audit_overlay_v14 = make_spatial_audit_overlay_v14

