def _v15_argument_parser() -> _source_v15.argparse.ArgumentParser:
    """Return a parser containing only v1.5-specific options."""
    parser = _source_v15.argparse.ArgumentParser(add_help=False)
    parser.add_argument('--trajectory-supergroup-gap-width-factor', type=float, default=3.0)
    parser.add_argument('--trajectory-max-rows-per-supergroup', type=int, default=10)
