    parser.add_argument('--trajectory-simpler-tie-tolerance', type=float, default=2.0)
    parser.add_argument('--sparse-trajectory-rescue-min-bic-improvement', type=float, default=6.0)
    parser.add_argument('--sparse-trajectory-rescue-min-rss-reduction', type=float, default=0.6)
    parser.add_argument('--sparse-trajectory-rescue-max-spacing-cv', type=float, default=0.25)
    parser.add_argument('--sparse-trajectory-rescue-min-detector-confidence', type=float, default=0.75)
    parser.add_argument('--sparse-trajectory-rescue-min-image-support-ratio', type=float, default=1.25)
