    parser.add_argument('--band-strong-boundary-gap-width-factor', type=float, default=1.5)
    parser.add_argument('--band-ambiguous-min-local-gap-ratio', type=float, default=1.25)
    parser.add_argument('--band-ambiguous-min-image-support-ratio', type=float, default=1.05)
    parser.add_argument('--band-boundary-min-longitudinal-overlap-fraction', type=float, default=0.2)
    parser.add_argument('--raw-evidence-stoma-exclusion-padding-fraction', type=float, default=0.1)
    parser.add_argument('--trajectory-stability-iterations', type=int, default=25)
    parser.add_argument('--trajectory-stability-jitter-width-fraction', type=float, default=0.03)
    parser.add_argument('--trajectory-stability-min-row-count-fraction', type=float, default=0.8)
