def _matched_trajectory_gap(first: dict[str, _source_v15.Any], second: dict[str, _source_v15.Any]) -> tuple[float, float]:
    """Median lateral gap and longitudinal-overlap fraction for two rows."""
    first_min = float(first['longitudinal_min_um'])
    first_max = float(first['longitudinal_max_um'])
    second_min = float(second['longitudinal_min_um'])
    second_max = float(second['longitudinal_max_um'])
    overlap_min = max(first_min, second_min)
    overlap_max = min(first_max, second_max)
    union_span = max(first_max, second_max) - min(first_min, second_min)
    overlap_span = max(0.0, overlap_max - overlap_min)
    overlap_fraction = overlap_span / union_span if union_span > 0 else 0.0
    if overlap_span > 0:
        positions = _source_v15.np.linspace(overlap_min, overlap_max, 31)
    else:
        positions = _source_v15.np.asarray([0.5 * (max(first_min, second_min) + min(first_max, second_max))])
    gaps = [abs(_source_v15.base.row_lateral_at(second, float(longitudinal)) - _source_v15.base.row_lateral_at(first, float(longitudinal))) for longitudinal in positions]
    return (float(_source_v15.np.median(gaps)), float(overlap_fraction))
_source_v15._matched_trajectory_gap = _matched_trajectory_gap

