def _remark_partial_band_eligibility_v15(row_records: list[dict[str, _source_v15.Any]], band_records: list[dict[str, _source_v15.Any]], point_assignment: dict[int, dict[str, _source_v15.Any]], stoma_traits: list[dict[str, _source_v15.Any]], median_detector_width_um: float, trajectory_slope: float, settings: _source_v15.TraitSettingsV15) -> list[dict[str, _source_v15.Any]]:
    """Recalculate field coverage along the fitted image-wide trajectory."""
    axis = _source_v15.v14._active_axis(stoma_traits)
    metadata = _source_v15.v14._ACTIVE_IMAGE_METADATA
    if axis is None or metadata is None:
        return [{'band_id': band['band_id'], 'provisional_band_id': band.get('provisional_band_id'), 'spatial_eligible': bool(band.get('band_spatial_eligible')), 'exclusion_reason': band.get('band_spatial_exclusion_reason', ''), 'v15_recalculation_available': False, 'v15_unavailable_reason': 'image_axis_or_metadata_unavailable'} for band in band_records]
    px_x = _source_v15.base.optional_float(metadata.get('metadata_pixels_per_um_x'))
    px_y = _source_v15.base.optional_float(metadata.get('metadata_pixels_per_um_y'))
    width_pixels = _source_v15.base.optional_int(metadata.get('image_width'))
    height_pixels = _source_v15.base.optional_int(metadata.get('image_height'))
    if px_x is None or px_y is None or width_pixels is None or (height_pixels is None):
        return [{'band_id': band['band_id'], 'provisional_band_id': band.get('provisional_band_id'), 'spatial_eligible': bool(band.get('band_spatial_eligible')), 'exclusion_reason': band.get('band_spatial_exclusion_reason', ''), 'v15_recalculation_available': False, 'v15_unavailable_reason': 'calibration_or_dimensions_unavailable'} for band in band_records]
