    height_um = height_pixels / px_y
    corners = [axis.forward(x, y) for x, y in ((0.0, 0.0), (width_um, 0.0), (0.0, height_um), (width_um, height_um))]
    image_long_min = min((item[1] for item in corners))
    image_long_max = max((item[1] for item in corners))
    measurements: list[dict[str, _source_v15.Any]] = []
    for band in band_records:
        observed_values = [float(stoma_traits[index]['longitudinal_coordinate_um']) for index in band['_point_indices']]
        observed = float(_source_v15.np.ptp(observed_values)) if observed_values else 0.0
        visible: list[float] = []
