    for assignment in point_assignment.values():
        provisional_id = str(assignment.get('provisional_band_id') or assignment.get('band_id'))
        diagnostic = diagnostics.get(provisional_id, {})
        assignment.update(_source_v15._trajectory_diagnostic_fields(diagnostic))
        assignment['trajectory_exact_row_band_traits_eligible'] = bool(assignment.get('trajectory_exact_row_band_traits_eligible') and assignment.get('trajectory_exact_row_traits_eligible'))
    if row_records and stoma_traits:
        longitudinal_min = min((float(row['longitudinal_coordinate_um']) for row in stoma_traits))
        longitudinal_max = max((float(row['longitudinal_coordinate_um']) for row in stoma_traits))
        order_at_minimum = [str(row['row_id']) for row in sorted(row_records, key=lambda item: _source_v15.base.row_lateral_at(item, longitudinal_min))]
        order_at_maximum = [str(row['row_id']) for row in sorted(row_records, key=lambda item: _source_v15.base.row_lateral_at(item, longitudinal_max))]
