def image_trait_summary_v15(image_metadata: dict[str, _source_v15.Any], stoma_traits: list[dict[str, _source_v15.Any]], hair_rows: list[dict[str, _source_v15.Any]] | None, row_records: list[dict[str, _source_v15.Any]], band_records: list[dict[str, _source_v15.Any]], axis: _source_v15.base.AxisTransform, spatial_probability: dict[str, _source_v15.Any], row_band_audit: dict[str, _source_v15.Any], width_um: float, height_um: float) -> dict[str, _source_v15.Any]:
    """Keep all measurements, while adding image-level trajectory eligibility."""
    result = _source_v15.v14.image_trait_summary_v14(image_metadata, stoma_traits, hair_rows, row_records, band_records, axis, spatial_probability, row_band_audit, width_um, height_um)
    eligible_bands = [band for band in band_records if bool(band.get('band_spatial_eligible'))]
    provisional: dict[str, dict[str, _source_v15.Any]] = {}
    for band in band_records:
        provisional.setdefault(str(band.get('provisional_band_id') or band.get('band_id')), band)
    unstable_groups = [band for band in provisional.values() if not bool(band.get('trajectory_row_count_stable'))]
    unresolved_bands = [band for band in eligible_bands if bool(band.get('trajectory_unresolved_boundary_candidate'))]
    ineligible_trajectory_bands = [band for band in eligible_bands if not bool(band.get('trajectory_exact_row_band_traits_eligible'))]
    unstable_eligible_groups = {str(band.get('provisional_band_id') or band.get('band_id')) for band in ineligible_trajectory_bands if not bool(band.get('trajectory_row_count_stable'))}
    ceiling_limited_eligible_groups = {str(band.get('provisional_band_id') or band.get('band_id')) for band in ineligible_trajectory_bands if bool(band.get('trajectory_maximum_k_reached'))}
    unresolved_sparse_eligible_groups = {str(band.get('provisional_band_id') or band.get('band_id')) for band in ineligible_trajectory_bands if bool(band.get('trajectory_unresolved_sparse_third_trajectory'))}
    unvalidated_singleton_eligible_groups = {str(band.get('provisional_band_id') or band.get('band_id')) for band in ineligible_trajectory_bands if bool(band.get('trajectory_singleton_validation_required')) and (not bool(band.get('trajectory_singleton_rows_validated')))}
    exact_gwas_eligible = bool(eligible_bands and (not ineligible_trajectory_bands))
    global_angle = row_band_audit.get('trajectory_image_wide_residual_angle', {})
    reasons: list[str] = []
    if not eligible_bands:
        reasons.append('no_spatially_complete_band')
    if unstable_eligible_groups:
        reasons.append('unstable_trajectory_row_count_or_assignment')
    if ceiling_limited_eligible_groups:
        reasons.append('trajectory_model_selected_configured_k_ceiling')
    if unresolved_sparse_eligible_groups:
        reasons.append('sparse_third_trajectory_lacks_local_raw_image_confirmation')
    if unvalidated_singleton_eligible_groups:
        reasons.append('singleton_supported_row_lacks_detector_or_local_edge_validation')
    if not bool(row_band_audit.get('trajectory_global_noncrossing', True)):
        reasons.append('fitted_trajectory_order_crosses_within_field')
    if not bool(row_band_audit.get('trajectory_supergroup_membership_stable', True)):
        reasons.append('broad_trajectory_supergroup_membership_near_threshold')
    if unresolved_bands:
        reasons.append('unresolved_trajectory_band_boundary')
    if any((not bool(band.get('trajectory_rows_within_expected_band_range')) for band in eligible_bands)):
        reasons.append('final_band_outside_expected_one_to_five_row_range')
    result.update({'row_model_version': _source_v15.SCRIPT_VERSION, 'trajectory_image_wide_orientation_enforced': True, 'trajectory_image_wide_residual_angle_deg': global_angle.get('angle_deg'), 'trajectory_image_wide_angle_confidence': global_angle.get('confidence'), 'trajectory_image_wide_angle_eligible_pair_count': global_angle.get('eligible_pair_count'), 'trajectory_image_wide_angle_support_gain_over_zero': global_angle.get('support_gain_over_zero'), 'trajectory_global_noncrossing': bool(row_band_audit.get('trajectory_global_noncrossing', True)), 'trajectory_noncrossing_constrained': True, 'trajectory_supergroup_membership_stable': bool(row_band_audit.get('trajectory_supergroup_membership_stable', True)), 'trajectory_supergroup_minimum_gap_classification_agreement': row_band_audit.get('trajectory_supergroup_membership_sensitivity', {}).get('minimum_classification_agreement_fraction'), 'biological_band_partition_count': max(0, len(band_records) - len(provisional)), 'trajectory_provisional_group_count': len(provisional), 'trajectory_unstable_provisional_group_count': len(unstable_groups), 'trajectory_stable_provisional_group_fraction': _source_v15.base.safe_divide(float(len(provisional) - len(unstable_groups)), float(len(provisional))), 'trajectory_unresolved_spatially_eligible_band_count': len(unresolved_bands), 'trajectory_ceiling_limited_spatially_eligible_group_count': len(ceiling_limited_eligible_groups), 'trajectory_unresolved_sparse_spatially_eligible_group_count': len(unresolved_sparse_eligible_groups), 'trajectory_unvalidated_singleton_spatially_eligible_group_count': len(unvalidated_singleton_eligible_groups), 'trajectory_ineligible_spatially_eligible_band_count': len(ineligible_trajectory_bands), 'trajectory_sparse_three_row_rescue_group_count': sum((bool(band.get('sparse_trajectory_rescue_applied')) for band in provisional.values())), 'trajectory_exact_row_band_traits_gwas_eligible': exact_gwas_eligible, 'trajectory_row_band_gwas_exclusion_reason': ';'.join(dict.fromkeys(reasons)), 'trajectory_row_band_trait_policy': 'detailed CSV retains experimental estimates; compact GWAS CSV blanks exact row/band phenotypes when any spatially eligible band has unstable row assignments, an unresolved band boundary, a ceiling-limited model, or an unconfirmed sparse third trajectory; density, morphometry and ordinary nearest-neighbour traits remain'})
    return result
_source_v15.image_trait_summary_v15 = image_trait_summary_v15
_source_v15._ROW_BAND_GWAS_TRAITS = ('stomatal_row_count', 'stomatal_band_count', 'stomatal_row_density_per_mm', 'stomatal_band_density_per_mm', 'within_row_stomatal_frequency_per_mm', 'rows_per_band_mean', 'single_row_band_fraction', 'two_row_band_fraction', 'three_row_band_fraction', 'four_plus_row_band_fraction', 'multirow_band_fraction', 'two_row_alternation_index_mean', 'adjacent_row_phase_offset_normalized_mean', 'same_row_empirical_probability', 'same_band_other_row_empirical_probability', 'adjacent_band_empirical_probability', 'other_band_empirical_probability', 'within_row_spacing_um_mean', 'within_band_interrow_spacing_um_mean', 'between_band_spacing_um_mean', 'band_width_um_mean', 'nearest_same_row_distance_um_mean', 'mean_two_sided_row_spacing_um_mean', 'nearest_lateral_row_distance_um_mean', 'nearest_other_row_same_band_distance_um_mean', 'nearest_other_band_row_distance_um_mean', 'stomata_per_row_mean', 'stomata_per_band_mean', 'row_continuity_mean', 'row_orientation_relative_leaf_axis_deg_mean', 'longitudinal_to_lateral_spacing_ratio', 'neighbor_relationship_entropy', 'neighbor_probability_longitudinal_lateral_anisotropy', 'relative_longitudinal_spacing_mean', 'relative_lateral_row_spacing_mean', 'row_band_spatial_stomatal_density_per_mm2', 'stomatal_band_density_complete_intervals_per_mm', 'stomatal_row_density_complete_intervals_per_mm')

def image_gwas_trait_summary_v15(image_traits: dict[str, _source_v15.Any]) -> dict[str, _source_v15.Any]:
    """Write trajectory QC and suppress only unstable row/band phenotypes."""
    summary = _source_v15.v14.image_gwas_trait_summary_v14(image_traits)
    for field in ('trajectory_provisional_group_count', 'trajectory_unstable_provisional_group_count', 'trajectory_stable_provisional_group_fraction', 'trajectory_unresolved_spatially_eligible_band_count', 'trajectory_ceiling_limited_spatially_eligible_group_count', 'trajectory_unresolved_sparse_spatially_eligible_group_count', 'trajectory_unvalidated_singleton_spatially_eligible_group_count', 'trajectory_ineligible_spatially_eligible_band_count', 'trajectory_sparse_three_row_rescue_group_count', 'trajectory_exact_row_band_traits_gwas_eligible', 'trajectory_row_band_gwas_exclusion_reason', 'trajectory_row_band_trait_policy', 'trajectory_image_wide_orientation_enforced', 'trajectory_image_wide_residual_angle_deg', 'trajectory_image_wide_angle_confidence', 'trajectory_image_wide_angle_eligible_pair_count', 'trajectory_image_wide_angle_support_gain_over_zero', 'trajectory_global_noncrossing', 'trajectory_noncrossing_constrained', 'trajectory_supergroup_membership_stable', 'trajectory_supergroup_minimum_gap_classification_agreement'):
        summary[field] = image_traits.get(field)
    if not bool(image_traits.get('trajectory_exact_row_band_traits_gwas_eligible')):
        for field in _source_v15._ROW_BAND_GWAS_TRAITS:
            summary[field] = None
    return summary
_source_v15.image_gwas_trait_summary_v15 = image_gwas_trait_summary_v15

def add_row_neighbors_v15(stoma_traits: list[dict[str, _source_v15.Any]], row_records: list[dict[str, _source_v15.Any]], point_assignment: dict[int, dict[str, _source_v15.Any]]) -> None:
    """Propagate trajectory QC to every stoma, then retain v1.4 eligibility."""
    for index, assignment in point_assignment.items():
        trajectory_qc = {key: value for key, value in assignment.items() if key == 'row_model_version' or key.startswith('trajectory_') or key.startswith('sparse_trajectory_')}
        stoma_traits[index].update(trajectory_qc)
