def _remark_partial_band_eligibility_v16(row_records: list[dict[str, _source_v16.Any]], band_records: list[dict[str, _source_v16.Any]], point_assignment: dict[int, dict[str, _source_v16.Any]], stoma_traits: list[dict[str, _source_v16.Any]], median_detector_width_um: float, trajectory_slope: float, settings: _source_v16.TraitSettingsV16) -> list[dict[str, _source_v16.Any]]:
    """Recalculate field coverage along each band's fitted row trajectories."""
    axis = _source_v16.v14._active_axis(stoma_traits)
    metadata = _source_v16.v14._ACTIVE_IMAGE_METADATA
    if axis is None or metadata is None:
        return _source_v16._V15_REMARK_PARTIAL_BAND_ELIGIBILITY(row_records, band_records, point_assignment, stoma_traits, median_detector_width_um, trajectory_slope, settings)
    px_x = _source_v16.base.optional_float(metadata.get('metadata_pixels_per_um_x'))
    px_y = _source_v16.base.optional_float(metadata.get('metadata_pixels_per_um_y'))
    width_pixels = _source_v16.base.optional_int(metadata.get('image_width'))
    height_pixels = _source_v16.base.optional_int(metadata.get('image_height'))
    if px_x is None or px_y is None or width_pixels is None or (height_pixels is None):
        return _source_v16._V15_REMARK_PARTIAL_BAND_ELIGIBILITY(row_records, band_records, point_assignment, stoma_traits, median_detector_width_um, trajectory_slope, settings)
    width_um = width_pixels / px_x
    height_um = height_pixels / px_y
    corners = [axis.forward(x, y) for x, y in ((0.0, 0.0), (width_um, 0.0), (0.0, height_um), (width_um, height_um))]
    image_long_min = min((item[1] for item in corners))
    image_long_max = max((item[1] for item in corners))
    row_lookup = {str(row['row_id']): row for row in row_records}
    measurements: list[dict[str, _source_v16.Any]] = []
    for band in band_records:
        observed_values = [float(stoma_traits[index]['longitudinal_coordinate_um']) for index in band['_point_indices']]
        observed = float(_source_v16.np.ptp(observed_values)) if observed_values else 0.0
        rows = [row_lookup[str(row_id)] for row_id in band.get('row_ids', []) if str(row_id) in row_lookup]
        visible: list[float] = []
        for longitudinal_um in _source_v16.np.linspace(image_long_min, image_long_max, 1200):
            if rows:
                lateral_um = float(_source_v16.np.median([_source_v16.base.row_lateral_at(row, float(longitudinal_um)) for row in rows]))
            else:
                lateral_um = float(band['band_center_lateral_um']) + trajectory_slope * float(longitudinal_um)
            x_um, y_um = axis.inverse(lateral_um, float(longitudinal_um))
            if 0.0 <= x_um <= width_um and 0.0 <= y_um <= height_um:
                visible.append(float(longitudinal_um))
        accessible = float(max(visible) - min(visible)) if len(visible) >= 2 else None
        edge_factor = _source_v16.base.optional_float(band.get('band_detector_side_edge_margin_box_width_factor'))
        edge_source = 'detector_bbox_source_pixels'
        if edge_factor is None:
            edge_factor = _source_v16.base.optional_float(band.get('band_rotated_lateral_edge_margin_box_width_factor'))
            edge_source = 'inherited_rotated_center_fallback'
        measurements.append({'band': band, 'observed': observed, 'accessible': accessible, 'coverage': _source_v16.base.safe_divide(observed, accessible), 'edge_factor': edge_factor, 'edge_source': edge_source})
    reference_pool = [item['observed'] for item in measurements if item['observed'] > 0 and (item['edge_factor'] is None or item['edge_factor'] > settings.partial_band_edge_margin_box_width_factor)]
    if not reference_pool:
        reference_pool = [item['observed'] for item in measurements if item['observed'] > 0]
    reference_span = float(_source_v16.np.median(reference_pool)) if reference_pool else None
    eligibility_audit: list[dict[str, _source_v16.Any]] = []
    basis = 'median_of_fitted_band_row_trajectories_clipped_to_source_field'
    for item in measurements:
        band = item['band']
        observed = float(item['observed'])
        coverage = item['coverage']
        relative_span = _source_v16.base.safe_divide(observed, reference_span)
        edge_factor = item['edge_factor']
        low_absolute = bool(coverage is not None and coverage < settings.partial_band_min_longitudinal_coverage_fraction)
        low_relative = bool(relative_span is not None and relative_span < settings.partial_band_min_relative_observed_span)
        edge_risk = bool(edge_factor is not None and edge_factor <= settings.partial_band_edge_margin_box_width_factor)
        excluded = bool(low_absolute and (low_relative or observed == 0.0) or (edge_risk and low_relative))
        reason = ''
        if excluded:
            reason = 'field_truncated_band_short_relative_span_at_lateral_edge' if edge_risk else 'incomplete_band_low_absolute_and_relative_longitudinal_span'
        band.update({'band_spatial_eligible': not excluded, 'band_fov_truncated': excluded, 'band_spatial_exclusion_reason': reason, 'band_observed_longitudinal_span_um': observed, 'band_accessible_longitudinal_span_um': item['accessible'], 'band_longitudinal_coverage_fraction': coverage, 'band_relative_observed_span': relative_span, 'partial_band_reference_span_um': reference_span, 'partial_band_accessible_span_basis': basis, 'band_lateral_edge_margin_source': item['edge_source']})
        for row_id in band.get('row_ids', []):
            row = row_lookup[str(row_id)]
            row['row_band_spatial_eligible'] = not excluded
            row['row_band_spatial_exclusion_reason'] = reason
            for index in row['_point_indices']:
                point_assignment[index]['row_band_spatial_eligible'] = not excluded
                point_assignment[index]['row_band_spatial_exclusion_reason'] = reason
        eligibility_audit.append({'band_id': band['band_id'], 'provisional_band_id': band.get('provisional_band_id'), 'spatial_eligible': not excluded, 'exclusion_reason': reason, 'observed_longitudinal_span_um': observed, 'accessible_longitudinal_span_um': item['accessible'], 'coverage_fraction': coverage, 'relative_observed_span': relative_span, 'lateral_edge_margin_box_width_factor': edge_factor, 'lateral_edge_margin_source': item['edge_source'], 'v16_recalculation_available': True, 'accessible_span_basis': basis})
    return eligibility_audit
_source_v16._remark_partial_band_eligibility_v16 = _remark_partial_band_eligibility_v16

