        low_relative: bool | None = None
        limited_relative_support: bool | None = None
        short_longitudinal_support: bool | None = None
        longitudinal_complete: bool | None = None
        longitudinal_status = 'unknown'
        longitudinal_reason = 'longitudinal_sampling_not_assessable'
        if longitudinal_assessable:
            low_absolute = bool(coverage < float(settings.partial_band_min_longitudinal_coverage_fraction))
            low_relative = bool(relative_span < float(settings.partial_band_min_relative_observed_span))
            short_longitudinal_support = bool(low_absolute and low_relative or observed_span <= 0.0)
            limited_relative_support = bool(observed_span > 0.0 and low_relative and (not low_absolute))
            longitudinal_complete = bool(observed_span > 0.0 and (not low_absolute) and (not low_relative))
