        for row in rows:
            row.update({'partial_band_eligibility_version': _source_v18.PARTIAL_BAND_ELIGIBILITY_VERSION, 'row_band_previous_v1_7_spatial_eligible': parent_eligible, 'row_band_previous_v1_7_spatial_exclusion_reason': parent_reason, 'row_structure_eligible': row_structure_eligible, 'row_band_lateral_half_cut': half_cut, 'row_band_lateral_half_cut_side': half_cut_side, 'row_band_lateral_same_side_half_cut_corroborated': same_side_corroborated, 'row_band_lateral_edge_assessment_state': lateral_state, 'row_band_lateral_edge_assessment_assessable': lateral_assessable, 'row_band_short_longitudinal_support': short_longitudinal_support, 'row_band_severe_short_observed_longitudinal_support': short_longitudinal_support, 'row_band_limited_relative_longitudinal_extent': limited_relative_support, 'row_band_low_relative_observed_support': low_relative, 'row_band_low_accessible_span_coverage': low_absolute, 'row_band_longitudinal_sampling_assessable': longitudinal_assessable, 'row_band_longitudinal_sampling_complete': longitudinal_complete, 'row_band_longitudinal_sampling_status': longitudinal_status, 'row_completeness_dependent_traits_eligible': completeness_eligible, 'row_band_spatial_eligible': row_structure_eligible, 'row_band_spatial_exclusion_reason': exclusion_reason})
            for index in row.get('_point_indices', []):
                if int(index) not in point_assignment:
                    continue
                point_assignment[int(index)].update({'partial_band_eligibility_version': _source_v18.PARTIAL_BAND_ELIGIBILITY_VERSION, 'row_structure_eligible': row_structure_eligible, 'row_band_lateral_half_cut': half_cut, 'row_band_lateral_half_cut_side': half_cut_side, 'row_band_lateral_same_side_half_cut_corroborated': same_side_corroborated, 'row_band_lateral_edge_assessment_state': lateral_state, 'row_band_lateral_edge_assessment_assessable': lateral_assessable, 'row_band_short_longitudinal_support': short_longitudinal_support, 'row_band_severe_short_observed_longitudinal_support': short_longitudinal_support, 'row_band_limited_relative_longitudinal_extent': limited_relative_support, 'row_band_low_relative_observed_support': low_relative, 'row_band_low_accessible_span_coverage': low_absolute, 'row_band_longitudinal_sampling_assessable': longitudinal_assessable, 'row_band_longitudinal_sampling_complete': longitudinal_complete, 'row_band_longitudinal_sampling_status': longitudinal_status, 'row_completeness_dependent_traits_eligible': completeness_eligible, 'row_band_spatial_eligible': row_structure_eligible, 'row_band_spatial_exclusion_reason': exclusion_reason})
        audit_record = dict(parent_record)
        audit_record.update({'band_id': band_id, 'provisional_band_id': band.get('provisional_band_id'), 'partial_band_eligibility_version': _source_v18.PARTIAL_BAND_ELIGIBILITY_VERSION, 'previous_v1_7_spatial_eligible': parent_eligible, 'previous_v1_7_exclusion_reason': parent_reason, 'spatial_eligible': row_structure_eligible, 'row_structure_eligible': row_structure_eligible, 'lateral_half_cut': half_cut, 'lateral_half_cut_side': half_cut_side, 'lateral_same_side_half_cut_corroborated': same_side_corroborated, 'fov_truncated': legacy_fov_truncated, 'confirmed_lateral_half_cut': half_cut, 'lateral_edge_assessment_state': lateral_state, 'lateral_edge_assessment_assessable': lateral_assessable, 'lateral_half_cut_decision_source': decision_source, 'lateral_half_cut_clearance_threshold_box_width_factor': member_clearance_limit, 'lateral_fitted_corroboration_threshold_box_width_factor': fitted_clearance_limit, 'lateral_edge_adjacent_buffer_box_width_factor': adjacent_buffer_limit, 'short_longitudinal_support': short_longitudinal_support, 'severe_short_observed_longitudinal_support': short_longitudinal_support, 'limited_relative_longitudinal_extent': limited_relative_support, 'low_relative_observed_support': low_relative, 'low_accessible_span_coverage': low_absolute, 'longitudinal_sampling_assessable': longitudinal_assessable, 'longitudinal_sampling_complete': longitudinal_complete, 'longitudinal_sampling_status': longitudinal_status, 'longitudinal_sampling_qc_reason': longitudinal_reason, 'completeness_dependent_traits_eligible': completeness_eligible, 'exclusion_reason': exclusion_reason, **geometry})
