def make_spatial_audit_overlay_v18(input_dir: _source_v18.Path, output_path: _source_v18.Path, image_metadata: dict[str, _source_v18.Any], stoma_traits: list[dict[str, _source_v18.Any]], row_records: list[dict[str, _source_v18.Any]], band_records: list[dict[str, _source_v18.Any]], axis: _source_v18.base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    """Add purple longitudinal-QC and gold lateral-edge-QC marks."""
