def image_trait_summary_v19(image_metadata: dict[str, _source_v19.Any], stoma_traits: list[dict[str, _source_v19.Any]], hair_rows: list[dict[str, _source_v19.Any]] | None, row_records: list[dict[str, _source_v19.Any]], band_records: list[dict[str, _source_v19.Any]], axis: _source_v19.base.AxisTransform, spatial_probability: dict[str, _source_v19.Any], row_band_audit: dict[str, _source_v19.Any], width_um: float, height_um: float) -> dict[str, _source_v19.Any]:
    """Keep v1.7 traits and add separate row/completeness summaries."""
    result = _source_v19.v17.image_trait_summary_v17(image_metadata, stoma_traits, hair_rows, row_records, band_records, axis, spatial_probability, row_band_audit, width_um, height_um)
    row_structure_bands = [band for band in band_records if bool(band.get('band_row_structure_eligible'))]
    strict_complete_bands = [band for band in band_records if bool(band.get('band_completeness_dependent_traits_eligible'))]
    longitudinally_complete_bands = [band for band in band_records if band.get('band_longitudinal_sampling_complete') is True]
    longitudinally_incomplete_bands = [band for band in band_records if band.get('band_longitudinal_sampling_complete') is False]
    longitudinally_unknown_bands = [band for band in band_records if band.get('band_longitudinal_sampling_complete') is None]
    strict_complete_band_ids = {str(band.get('band_id')) for band in strict_complete_bands}
    complete_rows = [row for row in row_records if str(row.get('band_id')) in strict_complete_band_ids and bool(row.get('row_completeness_dependent_traits_eligible'))]
    complete_stoma_indices = {int(index) for band in strict_complete_bands for index in band.get('_point_indices', [])}
    complete_row_accessible_length_um = sum((float(band.get('band_accessible_longitudinal_span_um') or 0.0) * int(band.get('row_count') or 0) for band in strict_complete_bands))
    complete_frequency = _source_v19.base.safe_divide(float(len(complete_stoma_indices)), complete_row_accessible_length_um / 1000.0 if complete_row_accessible_length_um > 0.0 else None)
    result.update(_source_v19.base.sample_summary((row.get('stoma_count') for row in complete_rows), 'stomata_per_completeness_eligible_row'))
    result.update(_source_v19.base.sample_summary((band.get('stoma_count') for band in strict_complete_bands), 'stomata_per_completeness_eligible_band'))
