def image_gwas_trait_summary_v19(image_traits: dict[str, _source_v19.Any]) -> dict[str, _source_v19.Any]:
    """Carry v1.9 eligibility traits/QC into the compact image table."""
    summary = _source_v19.v17.image_gwas_trait_summary_v17(image_traits)
    for field in _source_v19._V19_GWAS_FIELDS:
        summary[field] = image_traits.get(field)
    summary['row_geometry_model_version'] = _source_v19.ROW_GEOMETRY_MODEL_VERSION
    summary['trait_export_policy_version'] = _source_v19.TRAIT_EXPORT_POLICY_VERSION
    return summary
_source_v19.image_gwas_trait_summary_v19 = image_gwas_trait_summary_v19

def add_row_neighbors_v19(stoma_traits: list[dict[str, _source_v19.Any]], row_records: list[dict[str, _source_v19.Any]], point_assignment: dict[int, dict[str, _source_v19.Any]]) -> None:
    """Retain normal neighbor traits and propagate every v1.9 QC field."""
    _source_v19.v15.add_row_neighbors_v15(stoma_traits, row_records, point_assignment)
    for index, assignment in point_assignment.items():
        if not 0 <= int(index) < len(stoma_traits):
            continue
        eligibility_qc = {key: value for key, value in assignment.items() if key == 'partial_band_eligibility_version' or key.startswith('row_structure_') or key.startswith('row_band_lateral_') or key.startswith('row_band_short_') or key.startswith('row_band_severe_') or key.startswith('row_band_limited_') or key.startswith('row_band_low_') or key.startswith('row_band_longitudinal_') or key.startswith('row_completeness_') or key.startswith('row_band_spatial_')}
        stoma_traits[int(index)].update(eligibility_qc)
_source_v19.add_row_neighbors_v19 = add_row_neighbors_v19

def make_spatial_audit_overlay_v19(input_dir: _source_v19.Path, output_path: _source_v19.Path, image_metadata: dict[str, _source_v19.Any], stoma_traits: list[dict[str, _source_v19.Any]], row_records: list[dict[str, _source_v19.Any]], band_records: list[dict[str, _source_v19.Any]], axis: _source_v19.base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    """Add purple longitudinal-QC and gold lateral-edge-QC marks."""
    _source_v19.v15.make_spatial_audit_overlay_v15(input_dir, output_path, image_metadata, stoma_traits, row_records, band_records, axis, px_per_um_x, px_per_um_y)
    retained_longitudinal_qc = [band for band in band_records if bool(band.get('band_row_structure_eligible')) and band.get('band_longitudinal_sampling_complete') is False]
    retained_edge_uncertain = [band for band in band_records if bool(band.get('band_row_structure_eligible')) and band.get('band_lateral_edge_assessment_state') == 'edge_adjacent_uncertain']
    if not retained_longitudinal_qc and (not retained_edge_uncertain):
        return
    image = _source_v19.base.cv2.imread(str(output_path), _source_v19.base.cv2.IMREAD_COLOR)
    if image is None:
        return
    purple = (180, 0, 180)
    for band in retained_longitudinal_qc:
        members = [int(index) for index in band.get('_point_indices', [])]
        for index in members:
            x = int(round(stoma_traits[index]['center_x_pixels']))
            y = int(round(stoma_traits[index]['center_y_pixels']))
            _source_v19.base.cv2.rectangle(image, (x - 13, y - 13), (x + 13, y + 13), purple, 2, _source_v19.base.cv2.LINE_AA)
        if members:
            x = int(round(_source_v19.np.mean([stoma_traits[index]['center_x_pixels'] for index in members])))
            y = max(24, int(round(min((stoma_traits[index]['center_y_pixels'] for index in members)))) - 32)
            _source_v19.base.cv2.putText(image, f"{band['band_id']} LONGITUDINAL QC", (max(5, x - 105), y), _source_v19.base.cv2.FONT_HERSHEY_SIMPLEX, 0.45, purple, 2, _source_v19.base.cv2.LINE_AA)
    gold = (0, 190, 255)
    for band in retained_edge_uncertain:
        members = [int(index) for index in band.get('_point_indices', [])]
        for index in members:
            x = int(round(stoma_traits[index]['center_x_pixels']))
            y = int(round(stoma_traits[index]['center_y_pixels']))
            _source_v19.base.cv2.circle(image, (x, y), 18, gold, 2, _source_v19.base.cv2.LINE_AA)
        if members:
            x = int(round(_source_v19.np.mean([stoma_traits[index]['center_x_pixels'] for index in members])))
            y = min(image.shape[0] - 10, int(round(max((stoma_traits[index]['center_y_pixels'] for index in members)))) + 34)
            _source_v19.base.cv2.putText(image, f"{band['band_id']} LATERAL EDGE QC", (max(5, x - 105), y), _source_v19.base.cv2.FONT_HERSHEY_SIMPLEX, 0.45, gold, 2, _source_v19.base.cv2.LINE_AA)
    if not _source_v19.base.cv2.imwrite(str(output_path), image, [_source_v19.base.cv2.IMWRITE_PNG_COMPRESSION, 6]):
        raise RuntimeError(f'Failed to update v1.9 audit overlay: {output_path}')
_source_v19.make_spatial_audit_overlay_v19 = make_spatial_audit_overlay_v19

def install_v19_partial_band_policy() -> None:
    """Install v1.7 first and then replace only partial-band eligibility."""
    _source_v19.v17.install_v17_export_policy()
    _source_v19.v15._remark_partial_band_eligibility_v15 = _source_v19._remark_partial_band_eligibility_v19
    _source_v19.base.build_settings = _source_v19.build_settings_v19
    _source_v19.base.infer_rows_and_bands = _source_v19.infer_rows_and_bands_v19
    _source_v19.base.image_trait_summary = _source_v19.image_trait_summary_v19
    _source_v19.base.image_gwas_trait_summary = _source_v19.image_gwas_trait_summary_v19
    _source_v19.base.add_row_neighbors = _source_v19.add_row_neighbors_v19
    _source_v19.base.make_spatial_audit_overlay = _source_v19.make_spatial_audit_overlay_v19
    _source_v19.base.SCRIPT_VERSION = _source_v19.SCRIPT_VERSION
    _source_v19.base.__file__ = _source_v19.__file__
