    nearest_group = int(_source_v22.np.argmin(shared_distances))
    shared_residual_um = float(shared_distances[nearest_group])
    fallback_labels = point_map
    members = sorted((index for index, label in fallback_labels.items() if label == nearest_group and index != point_index))
    if len(members) < 2:
        return {'assessable': False, 'reason': 'removing_singleton_leaves_fewer_than_two_supported_points', 'nearest_fallback_group': nearest_group, 'shared_line_residual_um': shared_residual_um}
    member_longitudinal = _source_v22.np.asarray([float(longitudinal[index]) for index in members], dtype=float)
    member_lateral = _source_v22.np.asarray([float(lateral[index]) for index in members], dtype=float)
    order = _source_v22.np.argsort(member_longitudinal, kind='stable')
    member_longitudinal = member_longitudinal[order]
    member_lateral = member_lateral[order]
    bracketed = bool(float(member_longitudinal[0]) <= point_longitudinal <= float(member_longitudinal[-1]))
    unique_longitudinal = _source_v22.np.unique(member_longitudinal)
    gaps = _source_v22.np.diff(unique_longitudinal)
    median_gap = float(_source_v22.np.median(gaps)) if len(gaps) else None
    if bracketed and len(unique_longitudinal) >= 2:
        local_prediction = float(_source_v22.np.interp(point_longitudinal, member_longitudinal, member_lateral))
    else:
        if point_longitudinal < float(member_longitudinal[0]):
            selected = _source_v22.np.asarray([0, 1], dtype=int)
        else:
            selected = _source_v22.np.asarray([len(member_longitudinal) - 2, len(member_longitudinal) - 1], dtype=int)
        y_pair = member_longitudinal[selected]
        x_pair = member_lateral[selected]
        delta_y = float(y_pair[1] - y_pair[0])
        if abs(delta_y) <= 1e-09:
            local_slope = slope
        else:
            local_slope = float((x_pair[1] - x_pair[0]) / delta_y)
        slope_limit = _source_v22.math.tan(_source_v22.math.radians(float(settings.v20_singleton_local_direction_max_deviation_deg)))
        local_slope = float(_source_v22.np.clip(local_slope, -slope_limit, slope_limit))
        local_prediction = float(x_pair[-1] + local_slope * (point_longitudinal - y_pair[-1]) if point_longitudinal >= float(member_longitudinal[-1]) else x_pair[0] + local_slope * (point_longitudinal - y_pair[0]))
    local_residual_um = abs(point_lateral - local_prediction)
    conservative_continuation_residual_um = min(shared_residual_um, local_residual_um)
    extension_um = max(float(member_longitudinal[0]) - point_longitudinal, point_longitudinal - float(member_longitudinal[-1]), 0.0)
    if median_gap is not None and median_gap > 0:
        extension_limit_um = min(float(settings.v20_singleton_terminal_extension_median_gap_fraction) * median_gap, float(settings.v20_singleton_terminal_extension_max_width_factor) * median_detector_width_um)
    else:
        extension_limit_um = float(settings.v20_singleton_terminal_extension_fallback_width_factor) * median_detector_width_um
    other_gaps = [abs(float(value) - float(intercepts[nearest_group])) for group, value in enumerate(intercepts) if group != nearest_group]
    nearest_interrow_gap_um = min(other_gaps) if other_gaps else None
    cap_um = float(settings.v20_singleton_continuation_interrow_gap_cap_fraction) * nearest_interrow_gap_um if nearest_interrow_gap_um is not None else _source_v22.math.inf
