    distinct_threshold_um = max(float(settings.v20_singleton_distinct_minimum_um), float(settings.v20_singleton_continuation_unresolved_width_factor) * median_detector_width_um)
    if distinct_threshold_um < absorb_threshold_um:
        distinct_threshold_um = absorb_threshold_um
