    residuals = local_lateral - fitted
    rss = float(_source_v22.np.sum(residuals * residuals))
    raw_variance = rss / max(len(point_indices), 1)
    residual_floor_um = float(fallback.get('bic_residual_floor_um') or 0.0)
    bic_variance = max(raw_variance, residual_floor_um ** 2, 1e-09)
    k = int(fallback['k']) + 1
    bic = float(len(point_indices) * _source_v22.math.log(bic_variance) + 2 * k * _source_v22.math.log(max(len(point_indices), 2)))
