def _v22_leave_one_out_geometry(point_index: int, fallback: dict[str, _source_v22.Any], lateral: _source_v22.np.ndarray, longitudinal: _source_v22.np.ndarray, median_detector_width_um: float, settings: _source_v22.TraitSettingsV20) -> dict[str, _source_v22.Any]:
    """Measure one nominated point against its row after removing that point.

    Established memberships and the shared band slope are frozen.  This makes
    the test deliberately insensitive to an unrestricted higher-k model that
    fragments or rearranges otherwise coherent rows.
    """
    label_map = _source_v22._candidate_label_map(fallback)
    if point_index not in label_map:
        return {'assessable': False, 'reason': 'candidate_missing_from_fallback'}
    source_group = int(label_map[point_index])
    source_members = sorted((index for index, label in label_map.items() if int(label) == source_group))
    remaining_source = [index for index in source_members if index != point_index]
    if len(source_members) < int(settings.v22_loo_min_source_row_members):
        return {'assessable': False, 'reason': 'source_row_has_too_few_members_before_leave_one_out', 'source_group': source_group, 'source_row_member_count_before': len(source_members), 'source_row_member_count_after': len(remaining_source)}
    if len(remaining_source) < int(settings.v22_loo_min_remaining_row_members):
        return {'assessable': False, 'reason': 'source_row_has_too_few_members_after_leave_one_out', 'source_group': source_group, 'source_row_member_count_before': len(source_members), 'source_row_member_count_after': len(remaining_source)}
    width = max(float(median_detector_width_um), 1e-09)
    slope = float(fallback['slope'])
    reference = float(fallback['long_reference_um'])

    def adjusted(index: int) -> float:
        return float(lateral[index]) - slope * (float(longitudinal[index]) - reference)
    group_intercepts: dict[int, float] = {}
    for group in range(int(fallback['k'])):
        members = [index for index, label in label_map.items() if int(label) == group and index != point_index]
        if not members:
            return {'assessable': False, 'reason': 'leave_one_out_emptied_an_established_row', 'source_group': source_group}
        group_intercepts[group] = float(_source_v22.np.mean([adjusted(index) for index in members]))
    point_adjusted = adjusted(point_index)
    distances_by_group = {group: abs(point_adjusted - intercept) for group, intercept in group_intercepts.items()}
    nearest_group = min(distances_by_group, key=lambda group: (distances_by_group[group], group))
    source_shared_residual_um = float(distances_by_group[source_group])
    nearest_row_separation_um = float(distances_by_group[nearest_group])
    remaining_adjusted = _source_v22.np.asarray([adjusted(index) for index in remaining_source], dtype=float)
    source_intercept = float(group_intercepts[source_group])
    remaining_residuals = _source_v22.np.abs(remaining_adjusted - source_intercept)
    remaining_row_rms_um = float(_source_v22.math.sqrt(float(_source_v22.np.mean(remaining_residuals * remaining_residuals))))
    maximum_remaining_residual_um = float(_source_v22.np.max(remaining_residuals) if len(remaining_residuals) else 0.0)
    residual_dominance_ratio = source_shared_residual_um / max(maximum_remaining_residual_um, 0.05 * width, 1e-09)
    ordered_remaining = sorted(remaining_source, key=lambda index: (float(longitudinal[index]), int(index)))
    remaining_longitudinal = _source_v22.np.asarray([float(longitudinal[index]) for index in ordered_remaining], dtype=float)
    remaining_lateral = _source_v22.np.asarray([float(lateral[index]) for index in ordered_remaining], dtype=float)
    point_longitudinal = float(longitudinal[point_index])
    point_lateral = float(lateral[point_index])
    lower = remaining_longitudinal[remaining_longitudinal < point_longitudinal]
    upper = remaining_longitudinal[remaining_longitudinal > point_longitudinal]
    bracketed = bool(len(lower) and len(upper))
    local_prediction = float(_source_v22.np.interp(point_longitudinal, remaining_longitudinal, remaining_lateral)) if bracketed else None
    local_residual_um = abs(point_lateral - local_prediction) if local_prediction is not None else None
    source_longitudinal = _source_v22.np.sort(_source_v22.np.asarray([float(longitudinal[index]) for index in source_members], dtype=float))
    positive_source_gaps = _source_v22.np.diff(_source_v22.np.unique(source_longitudinal))
    positive_source_gaps = positive_source_gaps[positive_source_gaps > 1e-09]
    typical_source_gap_um = float(_source_v22.np.median(positive_source_gaps)) if len(positive_source_gaps) else None
    bracketing_interval_um = float(_source_v22.np.min(upper) - _source_v22.np.max(lower)) if bracketed else None
    bracketing_gap_ratio = bracketing_interval_um / typical_source_gap_um if bracketing_interval_um is not None and typical_source_gap_um is not None and (typical_source_gap_um > 0) else None
    other_group_separations = [float(distance) for group, distance in distances_by_group.items() if int(group) != source_group]
    nearest_other_established_row_um = min(other_group_separations) if other_group_separations else None
    other_row_points = [index for index, label in label_map.items() if int(label) != source_group]
    nearest_other_row_longitudinal_offset_um = min((abs(float(longitudinal[index]) - point_longitudinal) for index in other_row_points)) if other_row_points else None
    matched_longitudinal_lane_support = bool(nearest_other_row_longitudinal_offset_um is not None and typical_source_gap_um is not None and (nearest_other_row_longitudinal_offset_um <= max(0.5 * typical_source_gap_um, 0.5 * width)))
    local_width_factor = local_residual_um / width if local_residual_um is not None else None
    shared_width_factor = source_shared_residual_um / width
    remaining_rms_width_factor = remaining_row_rms_um / width
    nearest_row_width_factor = nearest_row_separation_um / width
    minimum_gap_um = max(float(settings.v22_loo_min_lateral_gap_um), float(settings.v22_loo_min_lateral_gap_width_factor) * width)
    maximum_gap_um = float(settings.v22_loo_max_lateral_gap_width_factor) * width
    gate_results = {'source_group_is_nearest': nearest_group == source_group, 'longitudinally_bracketed': bracketed, 'local_residual_passed': bool(local_width_factor is not None and local_width_factor >= float(settings.v22_loo_min_local_residual_width_factor)), 'shared_residual_passed': bool(shared_width_factor >= float(settings.v22_loo_min_shared_residual_width_factor)), 'remaining_row_rms_passed': bool(remaining_rms_width_factor <= float(settings.v22_loo_max_remaining_row_rms_width_factor)), 'residual_dominance_passed': bool(residual_dominance_ratio >= float(settings.v22_loo_min_residual_dominance_ratio)), 'bracketing_gap_passed': bool(bracketing_gap_ratio is not None and bracketing_gap_ratio <= float(settings.v22_loo_max_bracketing_gap_ratio)), 'within_existing_band_route_passed': bool(minimum_gap_um <= nearest_row_separation_um <= maximum_gap_um)}
    geometry_passed = all(gate_results.values())
    failed_gates = [key for key, passed in gate_results.items() if not passed]
    return {'assessable': True, 'reason': '' if geometry_passed else ';'.join(failed_gates), 'geometry_passed': geometry_passed, 'source_group': source_group, 'nearest_group': int(nearest_group), 'source_row_member_count_before': len(source_members), 'source_row_member_count_after': len(remaining_source), 'source_row_members_after_removal': remaining_source, 'shared_line_residual_um': source_shared_residual_um, 'shared_line_residual_width_factor': shared_width_factor, 'local_piecewise_residual_um': local_residual_um, 'local_piecewise_residual_width_factor': local_width_factor, 'remaining_row_rms_um': remaining_row_rms_um, 'remaining_row_rms_width_factor': remaining_rms_width_factor, 'maximum_remaining_residual_um': maximum_remaining_residual_um, 'residual_dominance_ratio': residual_dominance_ratio, 'longitudinally_bracketed': bracketed, 'bracketing_interval_um': bracketing_interval_um, 'typical_source_row_gap_um': typical_source_gap_um, 'bracketing_gap_ratio': bracketing_gap_ratio, 'nearest_row_separation_um': nearest_row_separation_um, 'nearest_row_separation_width_factor': nearest_row_width_factor, 'nearest_other_established_row_um': nearest_other_established_row_um, 'nearest_other_row_longitudinal_offset_um': nearest_other_row_longitudinal_offset_um, 'matched_longitudinal_lane_support': matched_longitudinal_lane_support, 'minimum_within_band_gap_um': minimum_gap_um, 'maximum_within_band_gap_um': maximum_gap_um, **gate_results}
