def _v22_leave_one_out_stability(point_index: int, fallback: dict[str, _source_v22.Any], lateral: _source_v22.np.ndarray, longitudinal: _source_v22.np.ndarray, median_detector_width_um: float, settings: _source_v22.TraitSettingsV20) -> dict[str, _source_v22.Any]:
    """Perturb the n-1 baseline and frozen hybrid without freeing memberships."""
    iterations = int(settings.trajectory_stability_iterations)
    point_indices = [int(value) for value in fallback.get('point_indices', [])]
    seed_offset = sum(((position + 1) * (index + 1) for position, index in enumerate(point_indices))) + 1009 * (int(point_index) + 1) + 22003
    rng = _source_v22.np.random.default_rng(int(settings.trajectory_stability_seed) + seed_offset)
    jitter_um = float(settings.trajectory_stability_jitter_width_fraction) * float(median_detector_width_um)
    fallback_k = int(fallback['k'])
