def make_spatial_audit_overlay_v20(input_dir: _source_v22.Path, output_path: _source_v22.Path, image_metadata: dict[str, _source_v22.Any], stoma_traits: list[dict[str, _source_v22.Any]], row_records: list[dict[str, _source_v22.Any]], band_records: list[dict[str, _source_v22.Any]], axis: _source_v22.base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    """Mark strict, v2.1 and v2.2 singleton routes distinctly."""
