    y_mean = float(_source_v23.np.mean(y))
    denominator = float(_source_v23.np.sum((x - x_mean) ** 2))
    slope = float(_source_v23.np.sum((x - x_mean) * (y - y_mean)) / denominator) if denominator > 1e-12 else 0.0
