def _replace_candidate_and_diagnostic(candidates: list[dict[str, _source_v23.Any]], diagnostic: dict[str, _source_v23.Any], hybrid: dict[str, _source_v23.Any], hybrid_diagnostic: dict[str, _source_v23.Any]) -> list[dict[str, _source_v23.Any]]:
    hybrid_k = int(hybrid['k'])
    updated: list[dict[str, _source_v23.Any]] = []
    replaced = False
    for candidate in candidates:
        if int(candidate.get('k', -1)) == hybrid_k and (not replaced):
            updated.append(hybrid)
            replaced = True
        else:
            updated.append(candidate)
    if not replaced:
        updated.append(hybrid)
        updated.sort(key=lambda item: int(item['k']))
    diagnostics: list[dict[str, _source_v23.Any]] = []
    diagnostic_replaced = False
    for item in diagnostic.get('candidate_diagnostics', []):
        if _source_v23.base.optional_int(item.get('candidate_row_count')) == hybrid_k and (not diagnostic_replaced):
            diagnostics.append(hybrid_diagnostic)
            diagnostic_replaced = True
        else:
            diagnostics.append(item)
    if not diagnostic_replaced:
        diagnostics.append(hybrid_diagnostic)
        diagnostics.sort(key=lambda item: int(item.get('candidate_row_count') or 0))
    diagnostic['candidate_diagnostics'] = diagnostics
    return updated
