def _rebuild_v23_band_group(parent_band: dict[str, _source_v23.Any], group: list[dict[str, _source_v23.Any]], stoma_traits: list[dict[str, _source_v23.Any]], median_detector_width_um: float, partition: dict[str, _source_v23.Any], group_index: int) -> dict[str, _source_v23.Any]:
    required_partition_fields = {'split', 'boundary_gap_um', 'gap_ratio', 'gap_width_factor', 'left_alternation', 'right_alternation', 'image_support_ratio'}
    missing_partition_fields = sorted(required_partition_fields.difference(partition))
