def make_spatial_audit_overlay_v23(input_dir: _source_v23.Path, output_path: _source_v23.Path, image_metadata: dict[str, _source_v23.Any], stoma_traits: list[dict[str, _source_v23.Any]], row_records: list[dict[str, _source_v23.Any]], band_records: list[dict[str, _source_v23.Any]], axis: _source_v23.base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    """Draw the established overlay and label every singleton route explicitly."""
    _source_v23.v19.make_spatial_audit_overlay_v19(input_dir, output_path, image_metadata, stoma_traits, row_records, band_records, axis, px_per_um_x, px_per_um_y)
    image = _source_v23.base.cv2.imread(str(output_path), _source_v23.base.cv2.IMREAD_COLOR)
    if image is None:
        return
    singleton_rows = [row for row in row_records if (_source_v23.base.optional_int(row.get('stoma_count')) or 0) == 1 and bool(row.get('trajectory_v20_singleton_rescue_applied'))]
    for row in singleton_rows:
        members = [int(value) for value in row.get('_point_indices', [])]
        if not members:
            continue
        point_index = members[0]
        x = int(round(float(stoma_traits[point_index]['center_x_pixels'])))
        y = int(round(float(stoma_traits[point_index]['center_y_pixels'])))
        singleton_band = bool(row.get('v20_singleton_band'))
        v21_relaxed = bool(row.get('trajectory_v21_membership_relaxation_applied'))
        leave_one_out = bool(row.get('trajectory_v22_leave_one_out_applied'))
        if leave_one_out:
            route = str(row.get('trajectory_v23_rescue_route') or '')
            if route == 'bracketed_3_to_2_plus_1':
                label = f"{row['row_id']} V2.3 BRACKETED SINGLETON ROW"
            elif route == 'terminal_refitted_remaining_row':
                label = f"{row['row_id']} V2.3 TERMINAL SINGLETON ROW"
            else:
                label = f"{row['row_id']} V2.2 LOO SINGLETON ROW"
            color = (255, 255, 255)
        elif v21_relaxed:
            color = (255, 0, 255)
            label = f"{row['row_id']} V2.1 RESCUED SINGLETON BAND" if singleton_band else f"{row['row_id']} V2.1 RESCUED SINGLETON ROW"
        else:
            color = (0, 165, 255) if singleton_band else (255, 255, 0)
            label = f"{row['row_id']} SINGLETON BAND" if singleton_band else f"{row['row_id']} SINGLETON ROW"
        if leave_one_out:
            _source_v23.base.cv2.circle(image, (x, y), 27, (0, 0, 0), 6, _source_v23.base.cv2.LINE_AA)
        _source_v23.base.cv2.circle(image, (x, y), 24, color, 3, _source_v23.base.cv2.LINE_AA)
        _source_v23.base.cv2.line(image, (x - 20, y), (x + 20, y), color, 2, _source_v23.base.cv2.LINE_AA)
        _source_v23.base.cv2.line(image, (x, y - 20), (x, y + 20), color, 2, _source_v23.base.cv2.LINE_AA)
        text_y = max(22, y - 30)
        if leave_one_out:
            _source_v23.base.cv2.putText(image, label, (max(5, x - 110), text_y), _source_v23.base.cv2.FONT_HERSHEY_SIMPLEX, 0.45, (0, 0, 0), 5, _source_v23.base.cv2.LINE_AA)
        _source_v23.base.cv2.putText(image, label, (max(5, x - 110), text_y), _source_v23.base.cv2.FONT_HERSHEY_SIMPLEX, 0.45, color, 2, _source_v23.base.cv2.LINE_AA)
    for row in row_records:
        members = [int(value) for value in row.get('_point_indices', [])]
        if members and bool(row.get('trajectory_v23_narrow_two_row_collapse_applied')):
            point_index = members[0]
            x = int(round(float(stoma_traits[point_index]['center_x_pixels'])))
            y = int(round(float(stoma_traits[point_index]['center_y_pixels'])))
            _source_v23.base.cv2.putText(image, f"{row['band_id']} V2.3 NARROW 2-TO-1 COLLAPSE", (max(5, x - 80), max(22, y - 24)), _source_v23.base.cv2.FONT_HERSHEY_SIMPLEX, 0.45, (255, 255, 255), 2, _source_v23.base.cv2.LINE_AA)
    if not _source_v23.base.cv2.imwrite(str(output_path), image, [_source_v23.base.cv2.IMWRITE_PNG_COMPRESSION, 6]):
        raise RuntimeError(f'Failed to update v2.3 audit overlay: {output_path}')
_source_v23.make_spatial_audit_overlay_v23 = make_spatial_audit_overlay_v23

def install_v23_policy() -> None:
    """Install v2.2, then replace only the audited v2.3 hooks."""
    _source_v23.parent.install_v20_singleton_policy()
    _source_v23.v15._trajectory_diagnostic_fields = _source_v23._trajectory_diagnostic_fields_v23
    _source_v23.v15.SCRIPT_VERSION = _source_v23.SCRIPT_VERSION
    _source_v23.v14.SCRIPT_VERSION = _source_v23.SCRIPT_VERSION
    _source_v23.v16.SCRIPT_VERSION = _source_v23.SCRIPT_VERSION
