def _linear_interval(coefficient: float, intercept: float, lower: float, upper: float) -> tuple[float, float] | None:
    if abs(coefficient) <= 1e-12:
        return (-_source_v24.math.inf, _source_v24.math.inf) if lower <= intercept <= upper else None
    first = (lower - intercept) / coefficient
    second = (upper - intercept) / coefficient
    return (min(first, second), max(first, second))
_source_v24._linear_interval = _linear_interval

def _visible_row_longitudinal_interval(row: dict[str, _source_v24.Any], axis: _source_v24.base.AxisTransform, width_um: float, height_um: float) -> tuple[float, float] | None:
    slope = float(row.get('row_common_slope_lateral_per_longitudinal') or 0.0)
    reference = float(row.get('row_longitudinal_reference_um') or 0.0)
    intercept = float(row['row_intercept_lateral_um']) - slope * reference
    sine = _source_v24.math.sin(axis.radians)
    cosine = _source_v24.math.cos(axis.radians)
    x_coefficient = cosine * slope + sine
    x_intercept = cosine * intercept + axis.origin_x_um
    y_coefficient = -sine * slope + cosine
    y_intercept = -sine * intercept + axis.origin_y_um
    x_interval = _source_v24._linear_interval(x_coefficient, x_intercept, 0.0, width_um)
    y_interval = _source_v24._linear_interval(y_coefficient, y_intercept, 0.0, height_um)
    if x_interval is None or y_interval is None:
        return None
    lower = max(x_interval[0], y_interval[0])
    upper = min(x_interval[1], y_interval[1])
    return (lower, upper) if lower <= upper else None
_source_v24._visible_row_longitudinal_interval = _visible_row_longitudinal_interval

def _row_endpoint_evidence(row: dict[str, _source_v24.Any], stoma_traits: list[dict[str, _source_v24.Any]], axis: _source_v24.base.AxisTransform | None, width_um: float | None, height_um: float | None) -> dict[str, _source_v24.Any]:
    members = [int(value) for value in row.get('_point_indices', [])]
    if not members or axis is None or width_um is None or (height_um is None):
        return {'assessable': False}
