    observed = _source_v24.np.asarray([float(stoma_traits[index]['longitudinal_coordinate_um']) for index in members], dtype=float)
    detector_heights = [value for value in (_source_v24._finite(stoma_traits[index].get('prediction_height_um')) or _source_v24._finite(stoma_traits[index].get('prediction_width_um')) for index in members) if value is not None and value > 0]
