def _lateral_sparse_border_evidence(band: dict[str, _source_v24.Any], is_outermost: bool, row_count: int, stoma_count: int, settings: _source_v24.TraitSettingsV24) -> dict[str, _source_v24.Any]:
    """Corroborate a one-stoma outer-band fragment on the relevant side."""
