            members = [int(value) for value in row.get('_point_indices', [])]
            if len(members) != 1:
                continue
            point_index = members[0]
            intercept = float(lateral[point_index]) - inherited_slope * float(longitudinal[point_index])
            row.update({'row_intercept_lateral_um': intercept, 'row_common_slope_lateral_per_longitudinal': inherited_slope, 'row_longitudinal_reference_um': 0.0, 'row_rms_lateral_residual_um': 0.0, 'row_orientation_relative_leaf_axis_deg': _source_v24.math.degrees(_source_v24.math.atan(inherited_slope)), 'row_tilt_slope_source': 'v24_singleton_inherits_band_median_local_slope', 'trajectory_v24_local_row_refit_applied': False})
