def _refresh_band_geometry(rows: list[dict[str, _source_v24.Any]], bands: list[dict[str, _source_v24.Any]], assignments: dict[int, dict[str, _source_v24.Any]], stoma_traits: list[dict[str, _source_v24.Any]], median_width_um: float) -> tuple[list[dict[str, _source_v24.Any]], list[dict[str, _source_v24.Any]], dict[int, dict[str, _source_v24.Any]]]:
    row_lookup = {str(row['row_id']): row for row in rows}
    refreshed: list[dict[str, _source_v24.Any]] = []
    for band in bands:
        linked = sorted([row_lookup[str(value)] for value in band.get('row_ids', [])], key=lambda row: _source_v24.base.row_lateral_at(row, 0.0))
        preserved = {key: value for key, value in band.items() if key.startswith('trajectory_v24_') or key.startswith('band_partition_') or key in {'provisional_band_id', 'v20_singleton_band'}}
        record = _source_v24._rebuild_band_v24(band, linked, stoma_traits, median_width_um, None, 1, preserved)
        refreshed.append(record)
