_source_v24._refresh_band_geometry = _refresh_band_geometry

def _assert_v24_invariants(stoma_traits: list[dict[str, _source_v24.Any]], rows: list[dict[str, _source_v24.Any]], bands: list[dict[str, _source_v24.Any]], assignments: dict[int, dict[str, _source_v24.Any]], eligibility_before: dict[str, list[bool | None]], settings: _source_v24.TraitSettingsV24) -> None:
    source = str(stoma_traits[0].get('source_image_name') or 'unknown_image') if stoma_traits else 'unknown_image'
    if set(assignments) != set(range(len(stoma_traits))):
        raise RuntimeError(f'v2.4 invariant failed: incomplete point assignment; source_image={source}.')
    row_ids = [str(row['row_id']) for row in rows]
    band_ids = [str(band['band_id']) for band in bands]
    if len(row_ids) != len(set(row_ids)) or len(band_ids) != len(set(band_ids)):
        raise RuntimeError(f'v2.4 invariant failed: duplicate row/band identifier; source_image={source}.')
    expected_bands = [f'B{index:03d}' for index in range(1, len(bands) + 1)]
    if band_ids != expected_bands:
        raise RuntimeError(f'v2.4 invariant failed: non-contiguous final band numbering; source_image={source}.')
    row_lookup = {str(row['row_id']): row for row in rows}
    seen_points: list[int] = []
    previous_center = -_source_v24.math.inf
    for band in bands:
        linked = [row_lookup[str(value)] for value in band.get('row_ids', [])]
        declared = len(linked)
        if declared > int(settings.maximum_rows_per_band):
            raise RuntimeError(f"v2.4 invariant failed: final band exceeds the biological row maximum; source_image={source}, band={band['band_id']}, rows={declared}, maximum={settings.maximum_rows_per_band}.")
        for field in ('row_count', 'automatic_row_count', 'row_count_used_for_traits'):
            if int(band.get(field) or -1) != declared:
                raise RuntimeError(f"v2.4 invariant failed: stale band row-count field; source_image={source}, band={band['band_id']}, field={field}.")
        center = float(band['band_center_lateral_um'])
        if center < previous_center:
            raise RuntimeError(f'v2.4 invariant failed: bands not ordered left-to-right; source_image={source}.')
        previous_center = center
        union = sorted({int(value) for row in linked for value in row.get('_point_indices', [])})
        if union != sorted((int(value) for value in band.get('_point_indices', []))):
            raise RuntimeError(f"v2.4 invariant failed: band members differ from linked-row union; source_image={source}, band={band['band_id']}.")
        seen_points.extend(union)
        for position, row in enumerate(linked, start=1):
            if str(row.get('band_id')) != str(band['band_id']):
                raise RuntimeError('v2.4 invariant failed: row-to-band link mismatch.')
            if not (int(row.get('row_position_within_band') or -1) == position and int(row.get('rows_in_band') or -1) == declared and (int(row.get('automatic_rows_in_band') or -1) == declared) and (int(row.get('band_row_count') or -1) == declared)):
                raise RuntimeError('v2.4 invariant failed: stale row band-count fields.')
            for point_index in row.get('_point_indices', []):
                assignment = assignments[int(point_index)]
                if str(assignment.get('row_id')) != str(row['row_id']) or str(assignment.get('band_id')) != str(band['band_id']):
                    raise RuntimeError('v2.4 invariant failed: point assignment mismatch.')
        if not bool(band.get('band_complete_topology_eligible')):
            if not (bool(band.get('band_lateral_is_leftmost_band')) or bool(band.get('band_lateral_is_rightmost_band'))):
                raise RuntimeError('v2.4 invariant failed: internal band excluded as an edge fragment.')
        if bool(band.get('band_edge_adequate_support_veto_applied')) and (not bool(band.get('band_complete_topology_eligible'))):
            raise RuntimeError('v2.4 invariant failed: adequate-support veto band was excluded.')
        if bool(band.get('band_edge_adequate_support_veto_applied')) and (not bool(band.get('band_edge_exclusion_candidate'))):
            raise RuntimeError('v2.4 invariant failed: adequate-support veto lacked an edge threat.')
        excluded = bool(band.get('band_edge_topology_excluded'))
        subtypes = (bool(band.get('band_lateral_half_cut_excluded')), bool(band.get('band_lateral_sparse_border_excluded')), bool(band.get('band_longitudinal_edge_fragment_excluded')))
        if excluded != bool(band.get('band_edge_fragment_excluded')):
            raise RuntimeError('v2.4 invariant failed: generic edge-exclusion flags disagree.')
        if excluded and sum(subtypes) != 1:
            raise RuntimeError('v2.4 invariant failed: excluded band lacks one unambiguous edge subtype.')
        if not excluded and any(subtypes):
            raise RuntimeError('v2.4 invariant failed: retained band carries an exclusion subtype.')
        expected_eligible = bool(band.get('band_complete_topology_eligible'))
        expected_reason = str(band.get('band_spatial_exclusion_reason') or '')
        for row in linked:
            if bool(row.get('row_complete_topology_eligible')) != expected_eligible:
                raise RuntimeError('v2.4 invariant failed: row/band topology eligibility disagrees.')
            if str(row.get('row_band_spatial_exclusion_reason') or '') != expected_reason:
                raise RuntimeError('v2.4 invariant failed: row/band exclusion reasons disagree.')
            for point_index in row.get('_point_indices', []):
                point = assignments[int(point_index)]
                if bool(point.get('row_complete_topology_eligible')) != expected_eligible:
                    raise RuntimeError('v2.4 invariant failed: point/band topology eligibility disagrees.')
                if str(point.get('row_band_spatial_exclusion_reason') or '') != expected_reason:
                    raise RuntimeError('v2.4 invariant failed: point/band exclusion reasons disagree.')
        if declared == 1 and int(band.get('stoma_count') or 0) == 1 and linked and bool(linked[0].get('trajectory_v24_singleton_applied')):
            raise RuntimeError('v2.4 invariant failed: a rescued singleton remained an isolated band.')
    if sorted(seen_points) != list(range(len(stoma_traits))):
        raise RuntimeError(f'v2.4 invariant failed: points duplicated or lost; source_image={source}.')
    for field, before in eligibility_before.items():
        after = [_source_v24.base.parse_bool(record.get(field)) for record in stoma_traits]
        if after != before:
            raise RuntimeError(f'v2.4 invariant failed: individual-complex eligibility changed; source_image={source}, field={field}.')
_source_v24._assert_v24_invariants = _assert_v24_invariants

