def image_trait_summary_v24(image_metadata: dict[str, _source_v24.Any], stoma_traits: list[dict[str, _source_v24.Any]], hair_rows: list[dict[str, _source_v24.Any]] | None, row_records: list[dict[str, _source_v24.Any]], band_records: list[dict[str, _source_v24.Any]], axis: _source_v24.base.AxisTransform, spatial_probability: dict[str, _source_v24.Any], row_band_audit: dict[str, _source_v24.Any], width_um: float, height_um: float) -> dict[str, _source_v24.Any]:
    result = _source_v24.v23.image_trait_summary_v23(image_metadata, stoma_traits, hair_rows, row_records, band_records, axis, spatial_probability, row_band_audit, width_um, height_um)
    reasons: list[str] = []
    for key, label in (('trajectory_v24_fragment_merge_count', 'local_fragment_merge'), ('trajectory_v24_singleton_rescue_count', 'expanded_singleton_rescue'), ('trajectory_v24_partition_split_count', 'band_split'), ('trajectory_v24_partition_reversal_count', 'band_split_reversal'), ('trajectory_v24_edge_fragment_excluded_band_count', 'edge_fragment_exclusion'), ('trajectory_v24_adequate_support_veto_band_count', 'adequate_support_veto')):
        if int(row_band_audit.get(key) or 0):
            reasons.append(f'v24_{label}_provisional')
    result.update({key: row_band_audit.get(key) for key in _source_v24._V24_IMAGE_FIELDS if key.startswith('trajectory_v24_')})
    result.update({'detected_row_count_v24': len(row_records), 'detected_band_count_v24': len(band_records), 'row_band_v24_qc_status': 'flagged_provisional_change' if reasons else 'pass_no_v24_change', 'row_band_v24_qc_flag': bool(reasons), 'row_band_v24_qc_reason': ';'.join(reasons), 'row_band_v24_value_interpretation': 'v2.4 values include guarded local row-fragment merging, frozen singleton scanning, image-supported band partitioning and final two-axis edge-completeness QC; changes remain provisional', 'row_geometry_model_version': _source_v24.SCRIPT_VERSION, 'partial_band_eligibility_version': _source_v24.SCRIPT_VERSION, 'trajectory_row_band_trait_policy': row_band_audit.get('trajectory_row_band_trait_policy')})
    return result
_source_v24.image_trait_summary_v24 = image_trait_summary_v24

