def add_row_neighbors_v24(stoma_traits: list[dict[str, _source_v24.Any]], row_records: list[dict[str, _source_v24.Any]], point_assignment: dict[int, dict[str, _source_v24.Any]]) -> None:
    _source_v24.v23.add_row_neighbors_v23(stoma_traits, row_records, point_assignment)
    for point_index, assignment in point_assignment.items():
        if not 0 <= int(point_index) < len(stoma_traits):
            continue
        stoma_traits[int(point_index)].update({key: value for key, value in assignment.items() if key.startswith('trajectory_v24_') or key.startswith('row_edge_') or key == 'row_complete_topology_eligible'})
