def make_spatial_audit_overlay_v24(input_dir: _source_v24.Path, output_path: _source_v24.Path, image_metadata: dict[str, _source_v24.Any], stoma_traits: list[dict[str, _source_v24.Any]], row_records: list[dict[str, _source_v24.Any]], band_records: list[dict[str, _source_v24.Any]], axis: _source_v24.base.AxisTransform, px_per_um_x: float, px_per_um_y: float) -> None:
    suppressed: list[tuple[dict[str, _source_v24.Any], _source_v24.Any, _source_v24.Any]] = []
    for row in row_records:
        candidate = _source_v24.base.optional_int(row.get('trajectory_v24_singleton_candidate_point_index'))
        members = [int(value) for value in row.get('_point_indices', [])]
        if bool(row.get('trajectory_v24_singleton_applied')) and candidate is not None and (candidate in members):
            suppressed.append((row, row.get('trajectory_v20_singleton_rescue_applied'), row.get('trajectory_v22_leave_one_out_applied')))
            row['trajectory_v20_singleton_rescue_applied'] = False
            row['trajectory_v22_leave_one_out_applied'] = False
    try:
        _source_v24.v23.make_spatial_audit_overlay_v23(input_dir, output_path, image_metadata, stoma_traits, row_records, band_records, axis, px_per_um_x, px_per_um_y)
    finally:
        for row, v20_value, v22_value in suppressed:
            row['trajectory_v20_singleton_rescue_applied'] = v20_value
            row['trajectory_v22_leave_one_out_applied'] = v22_value
    image = _source_v24.base.cv2.imread(str(output_path), _source_v24.base.cv2.IMREAD_COLOR)
    if image is None:
        return
    row_lookup = {str(row['row_id']): row for row in row_records}
    for band in band_records:
        members = [int(value) for value in band.get('_point_indices', [])]
        if not members:
            continue
        x = int(round(float(_source_v24.np.mean([stoma_traits[i]['center_x_pixels'] for i in members]))))
        y = int(round(float(_source_v24.np.mean([stoma_traits[i]['center_y_pixels'] for i in members]))))
        labels: list[tuple[str, tuple[int, int, int]]] = []
        if bool(band.get('trajectory_v24_partition_split_applied')):
            labels.append((f"{band['band_id']} V2.4 BAND SPLIT", (255, 255, 255)))
        if bool(band.get('trajectory_v24_partition_reversal_applied')):
            labels.append((f"{band['band_id']} V2.4 REATTACHED", (255, 0, 255)))
        if bool(band.get('band_lateral_half_cut_excluded')):
            labels.append((f"{band['band_id']} LATERAL HALF-CUT", (0, 0, 255)))
        elif bool(band.get('band_lateral_sparse_border_excluded')):
            labels.append((f"{band['band_id']} SPARSE LATERAL EDGE", (0, 0, 255)))
        elif bool(band.get('band_longitudinal_edge_fragment_excluded')):
            labels.append((f"{band['band_id']} LONGITUDINAL EDGE", (0, 0, 255)))
        if bool(band.get('band_edge_adequate_support_veto_applied')):
            labels.append((f"{band['band_id']} COMPLETE-SUPPORT RETAIN", (0, 255, 0)))
        for offset, (label, color) in enumerate(labels):
            _source_v24.base.cv2.putText(image, label, (max(5, x - 110), max(22, y - 28 - 18 * offset)), _source_v24.base.cv2.FONT_HERSHEY_SIMPLEX, 0.45, color, 2, _source_v24.base.cv2.LINE_AA)
    for row in row_records:
        candidate = _source_v24.base.optional_int(row.get('trajectory_v24_singleton_candidate_point_index'))
        members = [int(value) for value in row.get('_point_indices', [])]
        if not (bool(row.get('trajectory_v24_singleton_applied')) and candidate is not None and (candidate in members)):
            continue
        x = int(round(float(stoma_traits[candidate]['center_x_pixels'])))
        y = int(round(float(stoma_traits[candidate]['center_y_pixels'])))
        color = (0, 255, 255)
        _source_v24.base.cv2.circle(image, (x, y), 27, (0, 0, 0), 6, _source_v24.base.cv2.LINE_AA)
        _source_v24.base.cv2.circle(image, (x, y), 24, color, 3, _source_v24.base.cv2.LINE_AA)
        _source_v24.base.cv2.line(image, (x - 20, y), (x + 20, y), color, 2, _source_v24.base.cv2.LINE_AA)
        _source_v24.base.cv2.line(image, (x, y - 20), (x, y + 20), color, 2, _source_v24.base.cv2.LINE_AA)
        _source_v24.base.cv2.putText(image, f"{row['row_id']} V2.4 EXPANDED SINGLETON ROW", (max(5, x - 125), max(22, y - 30)), _source_v24.base.cv2.FONT_HERSHEY_SIMPLEX, 0.43, color, 2, _source_v24.base.cv2.LINE_AA)
    for row in row_records:
        if not bool(row.get('trajectory_v24_fragment_merge_applied')):
            continue
        members = [int(value) for value in row.get('_point_indices', [])]
        merged_members = sorted((int(value) for value in row.get('trajectory_v24_fragment_merge_point_indices', [])))
        if sorted(members) != merged_members:
            continue
        if not members:
            continue
        x = int(round(float(_source_v24.np.mean([stoma_traits[i]['center_x_pixels'] for i in members]))))
        y = int(round(float(_source_v24.np.mean([stoma_traits[i]['center_y_pixels'] for i in members]))))
