def _v25_partition_candidate(band: dict[str, _source_v25.Any], linked: list[dict[str, _source_v25.Any]], cut: int, gaps: list[float], boundary_evidence_by_rows: dict[tuple[str, str, str], dict[str, _source_v25.Any]], median_width_um: float, settings: _source_v25.TraitSettingsV25) -> dict[str, _source_v25.Any]:
    left = linked[:cut]
    right = linked[cut:]
    gap_um = float(gaps[cut - 1])
    other_gaps = [value for position, value in enumerate(gaps) if position != cut - 1]
    reference = float(_source_v25.np.median(_source_v25.np.asarray(other_gaps, dtype=float))) if other_gaps else None
    gap_ratio = gap_um / max(reference, 1e-09) if reference is not None else _source_v25.math.inf
    gap_factor = gap_um / max(median_width_um, 1e-09)
    provisional = str(band.get('provisional_band_id') or band.get('band_id') or '')
    boundary_key = (provisional, str(left[-1].get('row_id') or ''), str(right[0].get('row_id') or ''))
    inherited = boundary_evidence_by_rows.get(boundary_key)
    image_support_identity_exact = bool(inherited is not None and _source_v25.base.parse_bool(inherited.get('image_support_identity_exact')) is True and (str(inherited.get('provisional_band_id') or '') == boundary_key[0]) and (str(inherited.get('boundary_left_row_id') or '') == boundary_key[1]) and (str(inherited.get('boundary_right_row_id') or '') == boundary_key[2]) and (str(inherited.get('image_support_evidence_source') or '') == 'v25_direct_exact_pair_local_trajectory_parallel_flanks'))
    image_support = _source_v25._finite(inherited.get('image_support_ratio')) if image_support_identity_exact and inherited is not None else None
    stability = _source_v25.v22._strong_gap_stability(gap_um, median_width_um, settings, sum((ord(char) for char in provisional)) + cut + 2500)
    left_stomata = sum((int(row.get('stoma_count') or 0) for row in left))
    right_stomata = sum((int(row.get('stoma_count') or 0) for row in right))
    isolated_one_row_side = min(len(left), len(right)) == 1
    isolated_stomata = min(left_stomata, right_stomata) if isolated_one_row_side else None
    topology_tiers = {str(row.get('trajectory_v25_topology_confidence_tier') or 'not_assessed') for row in linked}
    topology_supported = bool(topology_tiers and topology_tiers.issubset({'supported', 'audited'}))
    nonlinear_topology = any((_source_v25.base.parse_bool(row.get('trajectory_v25_nonlinear_trajectory_suspected')) is True for row in linked))
    failures: list[str] = []
    if not topology_supported:
        failures.append('row_topology_not_supported')
    if nonlinear_topology:
        failures.append('nonlinear_row_topology')
    if gap_factor < float(settings.v25_partition_min_gap_width_factor):
        failures.append('gap_width')
    if gap_ratio < float(settings.v25_partition_min_local_gap_ratio):
        failures.append('local_gap_ratio')
    if stability < float(settings.v25_partition_min_stability_fraction):
        failures.append('boundary_stability')
    if min(left_stomata, right_stomata) < 1:
        failures.append('empty_side')
    decision_route = 'multirow_sides_strong_geometry'
    if isolated_one_row_side:
        if isolated_stomata is not None and isolated_stomata >= int(settings.v25_partition_min_stomata_per_side):
            decision_route = 'isolated_multipoint_row_geometry_plus_raw_image'
            if image_support is None or image_support < float(settings.v25_partition_min_image_support_ratio_isolated_row):
                failures.append('isolated_row_raw_image_support')
        else:
            decision_route = 'singleton_side_extra_strong_geometry_plus_raw_image'
            if gap_factor < float(settings.v25_partition_singleton_side_min_gap_width_factor):
                failures.append('singleton_side_gap_width')
            if image_support is None or image_support < float(settings.v25_partition_singleton_side_min_image_support_ratio):
                failures.append('singleton_side_raw_image_support')
    return {'provisional_band_id': provisional, 'boundary_left_row_id': boundary_key[1], 'boundary_right_row_id': boundary_key[2], 'cut': cut, 'left': left, 'right': right, 'gap_um': gap_um, 'gap_ratio': gap_ratio, 'gap_factor': gap_factor, 'image_support': image_support, 'image_support_identity_exact': image_support_identity_exact, 'image_support_evidence_source': inherited.get('image_support_evidence_source') if image_support_identity_exact and inherited is not None else None, 'raw_image_boundary_gradient': inherited.get('raw_image_boundary_gradient') if image_support_identity_exact and inherited is not None else None, 'raw_image_control_gradient_median': inherited.get('raw_image_control_gradient_median') if image_support_identity_exact and inherited is not None else None, 'image_support_control_boundary_count': inherited.get('image_support_control_boundary_count') if image_support_identity_exact and inherited is not None else 0, 'raw_image_control_source': inherited.get('raw_image_control_source') if image_support_identity_exact and inherited is not None else None, 'raw_image_support_sample_count': inherited.get('raw_image_support_sample_count') if image_support_identity_exact and inherited is not None else 0, 'raw_image_support_available': bool(image_support_identity_exact and inherited is not None and inherited.get('raw_image_support_available')), 'raw_image_support_unavailable_reason': inherited.get('raw_image_support_unavailable_reason') if inherited is not None else 'exact_boundary_identity_not_available', 'stability': stability, 'left_stomata': left_stomata, 'right_stomata': right_stomata, 'isolated_one_row_side': isolated_one_row_side, 'row_topology_confidence_tiers': sorted(topology_tiers), 'row_topology_supported': topology_supported, 'nonlinear_row_topology': nonlinear_topology, 'decision_route': decision_route, 'accepted': not failures, 'failed_gates': failures}
_source_v25._v25_partition_candidate = _v25_partition_candidate

def _is_v25_selected_singleton_row(row: dict[str, _source_v25.Any], stoma_traits: list[dict[str, _source_v25.Any]]) -> bool:
    members = [int(value) for value in row.get('_point_indices', [])]
    if len(members) != 1 or int(row.get('stoma_count') or 0) != 1:
        return False
    point_index = members[0]
    if not 0 <= point_index < len(stoma_traits):
        return False
    stoma_id = str(stoma_traits[point_index].get('stoma_id') or '')
    selected = {str(value) for value in row.get('trajectory_v25_selected_singleton_stoma_ids', [])}
    return bool(stoma_id and stoma_id in selected)
_source_v25._is_v25_selected_singleton_row = _is_v25_selected_singleton_row

def _direct_v25_boundary_evidence(row_records: list[dict[str, _source_v25.Any]], band_records: list[dict[str, _source_v25.Any]], stoma_traits: list[dict[str, _source_v25.Any]], median_detector_width_um: float, settings: _source_v25.TraitSettingsV25) -> dict[tuple[str, str, str], dict[str, _source_v25.Any]]:
    """Measure raw-image support for each exact original adjacent-row pair.

    V2.4 may contain legacy audit records whose support was matched to the
    nearest gap when the exact cut was not evaluated.  Those records are not
    safe for isolated-row decisions.  V2.5 therefore measures every original
    adjacent-row boundary directly and keys the result by the two stable row
    identities.  The score follows the mean local trajectory of the two rows
    over their overlap and compares it with parallel local flanks.  This is
    the established v1.5 raw-image definition, works when the provisional
    group has only two rows, and stays on the scale used by v2.4 thresholds.
    """
    row_lookup = {str(row.get('row_id') or ''): row for row in row_records}
    evidence: dict[tuple[str, str, str], dict[str, _source_v25.Any]] = {}
    for band in band_records:
        provisional = str(band.get('provisional_band_id') or band.get('band_id') or '')
        linked = sorted([row_lookup[str(row_id)] for row_id in band.get('row_ids', []) if str(row_id) in row_lookup], key=lambda row: _source_v25.base.row_lateral_at(row, 0.0))
        if len(linked) < 2:
            continue
        exclusion_boxes = _source_v25.v15._spatial_stoma_exclusion_boxes_pixels(stoma_traits, [int(value) for value in band.get('_point_indices', [])], settings.raw_evidence_stoma_exclusion_padding_fraction)
        for cut, (left_row, right_row) in enumerate(zip(linked[:-1], linked[1:], strict=True), start=1):
            left_id = str(left_row.get('row_id') or '')
            right_id = str(right_row.get('row_id') or '')
            boundary_lateral_um = float((_source_v25.base.row_lateral_at(left_row, 0.0) + _source_v25.base.row_lateral_at(right_row, 0.0)) / 2.0)
            boundary_slope = 0.5 * (float(left_row['row_common_slope_lateral_per_longitudinal']) + float(right_row['row_common_slope_lateral_per_longitudinal']))
            overlap_min = max(float(left_row['longitudinal_min_um']), float(right_row['longitudinal_min_um']))
            overlap_max = min(float(left_row['longitudinal_max_um']), float(right_row['longitudinal_max_um']))
            image_evidence = _source_v25.v15._trajectory_gradient_evidence(boundary_lateral_um, boundary_slope, 0.0, median_detector_width_um, longitudinal_min_um=overlap_min, longitudinal_max_um=overlap_max, exclusion_boxes_pixels=exclusion_boxes)
            key = (provisional, left_id, right_id)
            evidence[key] = {'provisional_band_id': provisional, 'boundary_left_row_id': key[1], 'boundary_right_row_id': key[2], 'boundary_original_cut': cut, 'boundary_lateral_um': boundary_lateral_um, 'boundary_slope_lateral_per_longitudinal': boundary_slope, 'boundary_longitudinal_overlap_min_um': overlap_min, 'boundary_longitudinal_overlap_max_um': overlap_max, 'raw_image_boundary_gradient': image_evidence.get('target_gradient_median'), 'raw_image_control_gradient_median': image_evidence.get('flank_gradient_median'), 'image_support_ratio': image_evidence.get('target_to_flank_ratio'), 'image_support_control_boundary_count': 0, 'raw_image_control_source': 'parallel_local_flanks', 'raw_image_support_available': bool(image_evidence.get('available')), 'raw_image_support_unavailable_reason': image_evidence.get('unavailable_reason', ''), 'raw_image_support_sample_count': image_evidence.get('sample_count', 0), 'image_support_evidence_source': 'v25_direct_exact_pair_local_trajectory_parallel_flanks', 'image_support_identity_exact': True}
    return evidence
_source_v25._direct_v25_boundary_evidence = _direct_v25_boundary_evidence

def _archive_and_neutralize_parent_band_state(rows: list[dict[str, _source_v25.Any]], assignments: dict[int, dict[str, _source_v25.Any]], band_templates: list[dict[str, _source_v25.Any]]) -> None:
    """Retain parent decisions as audit-only data, never active v2.5 state."""
    exact_active_fields = {'v20_singleton_band', 'v20_singleton_partition_applied'}
    active_prefixes = ('trajectory_v24_partition_', 'trajectory_v24_singleton_', 'band_partition_')
    for record in [*rows, *assignments.values(), *band_templates]:
        archived: dict[str, _source_v25.Any] = {}
        for key in list(record):
            if key not in exact_active_fields and (not key.startswith(active_prefixes)):
                continue
            value = record.get(key)
            archived[key] = value
            if isinstance(value, bool):
                record[key] = False
            elif isinstance(value, list):
                record[key] = []
            elif isinstance(value, dict):
                record[key] = {}
            elif isinstance(value, str):
                record[key] = ''
            else:
                record[key] = None
        record['trajectory_v25_parent_v24_active_band_state_audit_only'] = archived
        record['trajectory_v25_parent_v24_final_boundary_superseded'] = True
_source_v25._archive_and_neutralize_parent_band_state = _archive_and_neutralize_parent_band_state

def _partition_trajectory_bands_v25(row_records: list[dict[str, _source_v25.Any]], band_records: list[dict[str, _source_v25.Any]], point_assignment: dict[int, dict[str, _source_v25.Any]], stoma_traits: list[dict[str, _source_v25.Any]], median_detector_width_um: float, settings: _source_v25.TraitSettingsV25) -> tuple[list[dict[str, _source_v25.Any]], list[dict[str, _source_v25.Any]], dict[int, dict[str, _source_v25.Any]], list[dict[str, _source_v25.Any]]]:
    """Archive v2.4 cuts, reassess all boundaries, and enforce band capacity."""
    active_diagnostics = list(_source_v25.v14._ACTIVE_BAND_DIAGNOSTICS)
    if len(active_diagnostics) != len(band_records):
        raise RuntimeError(f'v2.5 partitioning requires one active diagnostic per provisional band; diagnostics={len(active_diagnostics)}, bands={len(band_records)}.')
    diagnostic_fields_by_provisional: dict[str, dict[str, _source_v25.Any]] = {}
    for provisional_band, diagnostic in zip(band_records, active_diagnostics, strict=True):
        provisional = str(provisional_band.get('band_id') or '')
        fields = _source_v25._trajectory_diagnostic_fields_v25(diagnostic)
        diagnostic_fields_by_provisional[provisional] = fields
        provisional_band.update(fields)
        provisional_band['provisional_band_id'] = provisional
    for row in row_records:
        provisional = str(row.get('provisional_band_id') or row.get('band_id') or '')
        row.update(diagnostic_fields_by_provisional.get(provisional, {}))
        row['provisional_band_id'] = provisional
    for assignment in point_assignment.values():
        provisional = str(assignment.get('provisional_band_id') or assignment.get('band_id') or '')
        assignment.update(diagnostic_fields_by_provisional.get(provisional, {}))
        assignment['provisional_band_id'] = provisional
    original_band_templates = [dict(band) for band in band_records]
    boundary_evidence_by_rows = _source_v25._direct_v25_boundary_evidence(row_records, band_records, stoma_traits, median_detector_width_um, settings)
    rows, bands, assignments, partition_audit = _source_v25.v24._partition_trajectory_bands_v24(row_records, band_records, point_assignment, stoma_traits, median_detector_width_um, settings)
    _source_v25._archive_and_neutralize_parent_band_state(rows, assignments, original_band_templates)
    row_lookup = {str(row['row_id']): row for row in rows}
    parent_v24_band_count = len(bands)
    for record in partition_audit:
        record['trajectory_v25_parent_v24_audit_only'] = True
        record['trajectory_v25_parent_v24_final_boundary_superseded'] = True
    bands = []
    for template in original_band_templates:
        provisional = str(template.get('provisional_band_id') or template.get('band_id') or '')
        linked = sorted([row_lookup[str(row_id)] for row_id in template.get('row_ids', [])], key=lambda row: _source_v25.base.row_lateral_at(row, 0.0))
        rebuilt_root = _source_v25.v24._rebuild_band_v24(template, linked, stoma_traits, median_detector_width_um, None, 1, {'trajectory_v25_parent_v24_partition_reassessed_globally': True, 'trajectory_v25_parent_v24_final_boundary_superseded': True, 'trajectory_v25_parent_v24_band_count_before_reassessment': parent_v24_band_count, 'trajectory_v25_partition_split_applied': False, 'trajectory_v25_additional_partition_split_applied': False, 'trajectory_v25_partition_split_depth': 0, 'trajectory_v25_partition_split_count_in_lineage': 0, 'trajectory_v25_capacity_forced_unvalidated_boundary': False, 'trajectory_v25_capacity_forced_unvalidated_boundary_in_lineage': False, 'v20_singleton_band': False, 'v20_singleton_partition_applied': False, 'trajectory_v24_singleton_applied': False})
        bands.append(rebuilt_root)
        partition_audit.append({'provisional_band_id': provisional, 'accepted': False, 'trajectory_v25_parent_v24_partition_reassessed_globally': True, 'trajectory_v25_parent_v24_final_boundary_superseded': True, 'trajectory_v25_reassessment_root_row_ids': [str(row.get('row_id') or '') for row in linked]})
    validated_singleton_boundaries: set[tuple[str, str, str]] = set()
    rejected_singleton_boundaries: set[tuple[str, str, str]] = set()
    reconciled = False
    while reconciled:
        reconciled = False
        bands.sort(key=lambda band: float(band['band_center_lateral_um']))
        for position, singleton_container in enumerate(bands):
            container_rows = [row_lookup[str(row_id)] for row_id in singleton_container.get('row_ids', [])]
            if not any((_source_v25._is_v25_selected_singleton_row(row, stoma_traits) for row in container_rows)):
                continue
            provisional = str(singleton_container.get('provisional_band_id') or singleton_container.get('band_id') or '')
            for neighbor_position in (position - 1, position + 1):
                if not 0 <= neighbor_position < len(bands):
                    continue
                neighbor = bands[neighbor_position]
                neighbor_provisional = str(neighbor.get('provisional_band_id') or neighbor.get('band_id') or '')
                if neighbor_provisional != provisional:
                    continue
                neighbor_rows = [row_lookup[str(row_id)] for row_id in neighbor.get('row_ids', [])]
                if not neighbor_rows:
                    continue
                combined = sorted(container_rows + neighbor_rows, key=lambda row: _source_v25.base.row_lateral_at(row, 0.0))
                container_ids = {str(row.get('row_id') or '') for row in container_rows}
                cuts = [cut for cut in range(1, len(combined)) if (str(combined[cut - 1].get('row_id') or '') in container_ids) != (str(combined[cut].get('row_id') or '') in container_ids)]
                if len(cuts) != 1:
                    raise RuntimeError('v2.5 singleton-boundary reconciliation could not identify one contiguous physical boundary.')
                cut = cuts[0]
                if not (_source_v25._is_v25_selected_singleton_row(combined[cut - 1], stoma_traits) or _source_v25._is_v25_selected_singleton_row(combined[cut], stoma_traits)):
                    continue
                boundary_key = (provisional, str(combined[cut - 1].get('row_id') or ''), str(combined[cut].get('row_id') or ''))
                if boundary_key in validated_singleton_boundaries:
                    continue
                gaps = [float(_source_v25.v15._matched_trajectory_gap(first, second)[0]) for first, second in zip(combined[:-1], combined[1:], strict=True)]
                assessment = _source_v25._v25_partition_candidate(singleton_container, combined, cut, gaps, boundary_evidence_by_rows, median_detector_width_um, settings)
                compact_assessment = {key: value for key, value in assessment.items() if key not in {'left', 'right'}}
                if bool(assessment['accepted']):
                    validated_singleton_boundaries.add(boundary_key)
                    validation_fields = {'trajectory_v25_inherited_singleton_boundary_validated': True, 'trajectory_v25_inherited_singleton_boundary_left_row_id': boundary_key[1], 'trajectory_v25_inherited_singleton_boundary_right_row_id': boundary_key[2], 'trajectory_v25_partition_image_support_ratio': assessment['image_support'], 'trajectory_v25_partition_image_support_identity_exact': assessment['image_support_identity_exact'], 'trajectory_v25_partition_image_support_evidence_source': assessment['image_support_evidence_source']}
                    boundary_entry = {'provisional_band_id': boundary_key[0], 'left_row_id': boundary_key[1], 'right_row_id': boundary_key[2]}
                    for boundary_band in (singleton_container, neighbor):
                        existing_boundaries = list(boundary_band.get('trajectory_v25_validated_inherited_singleton_boundaries', []))
                        if boundary_entry not in existing_boundaries:
                            existing_boundaries.append(boundary_entry)
                        boundary_band.update(validation_fields)
                        boundary_band['trajectory_v25_validated_inherited_singleton_boundaries'] = existing_boundaries
                        boundary_band['trajectory_v25_validated_inherited_singleton_boundary_count'] = len(existing_boundaries)
                    partition_audit.append({'provisional_band_id': provisional, 'accepted': True, **validation_fields, 'trajectory_v25_partition_candidate_diagnostics': [compact_assessment]})
                    continue
                if len(combined) > int(settings.maximum_rows_per_band):
                    validated_singleton_boundaries.add(boundary_key)
                    unavailable_fields = {'trajectory_v25_inherited_singleton_boundary_revalidation_required': True, 'trajectory_v25_inherited_singleton_boundary_revalidation_unavailable': True, 'trajectory_v25_inherited_singleton_boundary_retained_due_capacity': True, 'trajectory_v25_inherited_singleton_boundary_left_row_id': boundary_key[1], 'trajectory_v25_inherited_singleton_boundary_right_row_id': boundary_key[2]}
