def _missing_length_through_relevant_lateral_side(reference_interval: tuple[float, float], visible_interval: tuple[float, float] | None, x_coefficient: float, x_intercept: float, width_um: float, relevant_sides: set[str]) -> float:
    low, high = reference_interval
    segments: list[tuple[float, float]] = []
    if visible_interval is None:
        segments.append((low, high))
    else:
        visible_low = max(low, float(visible_interval[0]))
        visible_high = min(high, float(visible_interval[1]))
        if visible_low > low:
            segments.append((low, min(visible_low, high)))
        if visible_high < high:
            segments.append((max(visible_high, low), high))
    missing = 0.0
    for start, stop in segments:
        if stop <= start:
            continue
        midpoint = 0.5 * (start + stop)
        x = x_coefficient * midpoint + x_intercept
        exits_left = x < -1e-09 and 'left' in relevant_sides
        exits_right = x > width_um + 1e-09 and 'right' in relevant_sides
        if exits_left or exits_right:
            missing += stop - start
    return missing
_source_v25._missing_length_through_relevant_lateral_side = _missing_length_through_relevant_lateral_side

def _v25_multirow_edge_evidence(band: dict[str, _source_v25.Any], rows: list[dict[str, _source_v25.Any]], axis: _source_v25.base.AxisTransform | None, width_um: float | None, height_um: float | None, is_outermost: bool, settings: _source_v25.TraitSettingsV25) -> dict[str, _source_v25.Any]:
    if not is_outermost or len(rows) < 2:
        return {'assessable': False, 'reason': 'not_an_outermost_multirow_band', 'triggered': False}
    if axis is None or width_um is None or height_um is None:
        return {'assessable': False, 'reason': 'source_geometry_or_calibration_unavailable', 'triggered': False}
    if _source_v25.base.parse_bool(band.get('trajectory_row_count_stable')) is not True:
        return {'assessable': False, 'reason': 'row_count_not_explicitly_stable', 'triggered': False}
