        supported_ids = {str(value) for value in row.get('trajectory_v25_supported_singleton_stoma_ids', [])}
        ambiguous_ids = {str(value) for value in row.get('trajectory_v25_ambiguous_singleton_stoma_ids', [])}
        stoma_id = str(stoma_traits[members[0]].get('stoma_id') or '') if len(members) == 1 else ''
        is_singleton = len(members) == 1 and stoma_id in supported_ids | ambiguous_ids
        if is_singleton and stoma_id in supported_ids:
            tier = 'supported'
        elif is_singleton:
            tier = 'ambiguous'
        else:
            tier = 'not_singleton'
        row.update({'trajectory_v25_singleton_row': is_singleton, 'trajectory_v25_singleton_evidence_tier': tier, 'trajectory_v25_singleton_orientation_inherited': is_singleton, 'trajectory_v25_singleton_orientation_independently_estimable': False if is_singleton else None, 'trajectory_v25_singleton_within_row_spacing_estimable': False if is_singleton else len(members) >= 2})
        for point_index in members:
            point_stoma_id = str(stoma_traits[point_index].get('stoma_id') or '')
            point_singleton = bool(is_singleton and point_stoma_id == stoma_id)
            assignments[int(point_index)].update({'trajectory_v25_singleton_stoma': point_singleton, 'trajectory_v25_singleton_evidence_tier': tier if point_singleton else 'not_singleton', 'trajectory_v25_singleton_orientation_inherited': point_singleton, 'trajectory_v25_singleton_orientation_independently_estimable': False if point_singleton else None})
