    values.update({'detected_row_count_v25': len(row_records), 'detected_band_count_v25': len(band_records), 'detected_row_count_v25_lower_bound': row_band_audit.get('detected_row_count_v25_lower_bound'), 'detected_row_count_v25_upper_bound': row_band_audit.get('detected_row_count_v25_upper_bound'), 'supported_singleton_row_fraction_v25': supported / len(row_records) if row_records else None, 'ambiguous_singleton_row_fraction_v25': ambiguous / len(row_records) if row_records else None, 'row_band_v25_qc_status': 'flagged_provisional_change_or_uncertainty' if reasons else 'pass_no_v25_change', 'row_band_v25_qc_flag': bool(reasons), 'row_band_v25_qc_reason': ';'.join(reasons), 'row_band_v25_value_interpretation': 'v2.5 best estimates include joint local-angle row assignment; supported singletons contribute to the primary topology, selected ambiguous singletons remain in the best estimate but are explicitly represented by QC and bounds, and confirmed edge-censored bands are excluded only from complete row/band topology traits', 'row_geometry_model_version': _source_v25.SCRIPT_VERSION, 'partial_band_eligibility_version': _source_v25.SCRIPT_VERSION, 'trajectory_row_band_trait_policy': row_band_audit.get('trajectory_row_band_trait_policy')})
