_source_v252._V252_ROW_DEFAULTS: dict[str, _source_v252.Any] = {'trajectory_v252_policy_version': _source_v252.SCRIPT_VERSION, 'trajectory_v252_general_row_simplification_applied': False, 'trajectory_v252_general_row_simplification_route': 'not_applied', 'trajectory_v252_general_row_simplification_score_cost': None, 'trajectory_v252_general_row_simplification_geometry': {}, 'trajectory_v252_edge_touching_singleton_rule_applied': False, 'trajectory_v252_edge_touching_singleton_absorbed_count': 0, 'trajectory_v252_edge_touching_singleton_absorbed': [], 'trajectory_v252_edge_touching_singleton_pending_topology_removal_count': 0, 'trajectory_v252_edge_touching_singleton_pending_topology_removal': [], 'trajectory_v252_edge_touch_tolerance_pixels': _source_v252.V252_EDGE_TOUCH_TOLERANCE_PIXELS}

def _edge_touch_details(point_index: int, settings: _source_v252.TraitSettingsV252) -> dict[str, _source_v252.Any]:
    record = _source_v252.v25._active_record(int(point_index))
    metadata = _source_v252.v14._ACTIVE_IMAGE_METADATA or {}
    if record is None:
        return {'assessable': False, 'touches': False, 'sides': []}
    width = _source_v252.base.optional_float(metadata.get('image_width'))
    height = _source_v252.base.optional_float(metadata.get('image_height'))
    x1 = _source_v252.base.optional_float(record.get('prediction_x1_pixels'))
    y1 = _source_v252.base.optional_float(record.get('prediction_y1_pixels'))
    x2 = _source_v252.base.optional_float(record.get('prediction_x2_pixels'))
    y2 = _source_v252.base.optional_float(record.get('prediction_y2_pixels'))
    assessable = all((value is not None for value in (width, height, x1, y1, x2, y2)))
    sides: list[str] = []
    if assessable:
        tolerance = float(settings.v252_edge_touch_tolerance_pixels)
        if float(x1) <= tolerance:
            sides.append('left')
        if float(x2) >= float(width) - tolerance:
            sides.append('right')
        if float(y1) <= tolerance:
            sides.append('top')
        if float(y2) >= float(height) - tolerance:
            sides.append('bottom')
    return {'assessable': assessable, 'touches': bool(sides), 'sides': sides, 'tolerance_pixels': float(settings.v252_edge_touch_tolerance_pixels), 'prediction_x1_pixels': x1, 'prediction_y1_pixels': y1, 'prediction_x2_pixels': x2, 'prediction_y2_pixels': y2, 'image_width_pixels': width, 'image_height_pixels': height}
_source_v252._edge_touch_details = _edge_touch_details

def _candidate_records(candidates: list[dict[str, _source_v252.Any]], lateral: _source_v252.np.ndarray, longitudinal: _source_v252.np.ndarray, median_width_um: float, settings: _source_v252.TraitSettingsV252) -> list[dict[str, _source_v252.Any]]:
    retained: dict[tuple[_source_v252.Any, ...], dict[str, _source_v252.Any]] = {}
    for candidate in candidates:
        record = _source_v252.v25._evaluate_joint_candidate(candidate, lateral, longitudinal, median_width_um, settings)
        key = (record['canonical_partition'], round(float(record['slope_angle_deg']), 10))
        previous = retained.get(key)
        if previous is None or float(record['adjusted_score']) < float(previous['adjusted_score']):
            retained[key] = record
    return list(retained.values())
_source_v252._candidate_records = _candidate_records

def _clean_single_fragment_merge(selected: dict[str, _source_v252.Any], simpler: dict[str, _source_v252.Any]) -> tuple[int, int] | None:
    """Return the two selected groups joined by a pure k -> k-1 merge.

    Every selected group must remain intact, all unaffected groups must be
    identical, and exactly two adjacent lateral groups must map to one simpler
    group.  Any broad reassignment is rejected by this route.
    """
    selected_groups = [set(group) for group in _source_v252.v25._candidate_group_members(selected)]
    simpler_groups = [set(group) for group in _source_v252.v25._candidate_group_members(simpler)]
    owners: list[int] = []
    for group in selected_groups:
        matches = [index for index, target in enumerate(simpler_groups) if group <= target]
        if len(matches) != 1:
            return None
        owners.append(matches[0])
    counts = [owners.count(index) for index in range(len(simpler_groups))]
    if counts.count(2) != 1 or any((value not in {1, 2} for value in counts)):
        return None
    merged_owner = counts.index(2)
    pair = [index for index, owner in enumerate(owners) if owner == merged_owner]
    if len(pair) != 2 or pair[1] != pair[0] + 1:
        return None
    for owner, target in enumerate(simpler_groups):
        components = [selected_groups[index] for index, assigned_owner in enumerate(owners) if assigned_owner == owner]
        if not components or set().union(*components) != target:
            return None
    return (pair[0], pair[1])
_source_v252._clean_single_fragment_merge = _clean_single_fragment_merge

def _fragment_continuity_geometry(selected: dict[str, _source_v252.Any], simpler_record: dict[str, _source_v252.Any], pair: tuple[int, int], longitudinal: _source_v252.np.ndarray, settings: _source_v252.TraitSettingsV252) -> dict[str, _source_v252.Any]:
    groups = _source_v252.v25._candidate_group_members(selected)
    first = groups[pair[0]]
    second = groups[pair[1]]
    first_long = _source_v252.np.asarray([float(longitudinal[index]) for index in first], dtype=float)
    second_long = _source_v252.np.asarray([float(longitudinal[index]) for index in second], dtype=float)
    overlap = max(0.0, min(float(_source_v252.np.max(first_long)), float(_source_v252.np.max(second_long))) - max(float(_source_v252.np.min(first_long)), float(_source_v252.np.min(second_long))))
    overlap_reference = max(min(float(_source_v252.np.ptp(first_long)), float(_source_v252.np.ptp(second_long))), 1e-09)
    overlap_fraction = overlap / overlap_reference
    combined_members = len(first) + len(second)
    maximum_rms = float(simpler_record['maximum_ordinary_row_rms_width_factor'])
    failures: list[str] = []
    if combined_members < int(settings.v252_fragment_min_combined_members):
        failures.append('too_few_combined_members')
    if overlap_fraction > float(settings.v252_fragment_max_longitudinal_overlap_fraction):
        failures.append('fragments_overlap_longitudinally')
    if maximum_rms > float(settings.v252_fragment_max_ordinary_rms_width_factor):
        failures.append('simpler_model_row_rms')
    return {'selected_group_pair': list(pair), 'selected_fragment_member_counts': [len(first), len(second)], 'combined_member_count': combined_members, 'longitudinal_overlap_fraction': overlap_fraction, 'simpler_maximum_ordinary_row_rms_width_factor': maximum_rms, 'passed': not failures, 'failed_gates': failures}
_source_v252._fragment_continuity_geometry = _fragment_continuity_geometry

def _choose_general_simplification(chosen: dict[str, _source_v252.Any], records: list[dict[str, _source_v252.Any]], longitudinal: _source_v252.np.ndarray, settings: _source_v252.TraitSettingsV252) -> tuple[dict[str, _source_v252.Any], dict[str, _source_v252.Any], str, dict[str, _source_v252.Any]] | None:
    selected_record = next((record for record in records if record['canonical_partition'] == _source_v252.v25._canonical_partition(chosen) and _source_v252.math.isclose(float(record['slope_angle_deg']), _source_v252.math.degrees(_source_v252.math.atan(float(chosen.get('slope') or 0.0))), rel_tol=0.0, abs_tol=1e-08)), None)
    if selected_record is None:
        return None
    selected_k = int(chosen.get('k') or 0)
    baseline_k = _source_v252.base.optional_int(chosen.get('trajectory_v25_baseline_row_count'))
    if not bool(chosen.get('trajectory_v25_joint_change_applied')):
        return None
    if baseline_k is None or selected_k <= baseline_k:
        return None
    alternatives = [record for record in records if bool(record.get('valid')) and int(record['candidate_row_count']) == selected_k - 1]
    if not alternatives:
        return None
    simpler_record = min(alternatives, key=lambda record: (float(record['adjusted_score']), int(record['singleton_row_count']), abs(float(record['slope_angle_deg']))))
    score_cost = float(simpler_record['adjusted_score']) - float(selected_record['adjusted_score'])
    if selected_k >= int(settings.v252_fragment_min_selected_rows):
        pair = _source_v252._clean_single_fragment_merge(chosen, simpler_record['candidate'])
        if pair is not None:
            geometry = _source_v252._fragment_continuity_geometry(chosen, simpler_record, pair, longitudinal, settings)
            if bool(geometry['passed']) and score_cost <= float(settings.v252_fragment_max_score_cost):
                return (simpler_record['candidate'], simpler_record, 'longitudinal_fragment_continuity', {**geometry, 'score_cost': score_cost})
    selected_sizes = [len(group) for group in _source_v252.v25._candidate_group_members(chosen)]
    simpler_sizes = [len(group) for group in _source_v252.v25._candidate_group_members(simpler_record['candidate'])]
    capacity = int(settings.trajectory_max_rows_per_supergroup)
    capacity_passed = bool(selected_k == capacity and all((value >= 2 for value in selected_sizes)) and all((value >= int(settings.v252_capacity_simplification_min_members_per_row) for value in simpler_sizes)) and (score_cost <= float(settings.v252_capacity_simplification_max_score_cost)) and (float(simpler_record['maximum_ordinary_row_rms_width_factor']) <= float(settings.v252_fragment_max_ordinary_rms_width_factor)))
    if capacity_passed:
        return (simpler_record['candidate'], simpler_record, 'balanced_capacity_bound_simplification', {'selected_row_count': selected_k, 'selected_cluster_sizes': selected_sizes, 'simpler_cluster_sizes': simpler_sizes, 'simpler_maximum_ordinary_row_rms_width_factor': float(simpler_record['maximum_ordinary_row_rms_width_factor']), 'score_cost': score_cost, 'passed': True, 'failed_gates': []})
    return None
_source_v252._choose_general_simplification = _choose_general_simplification

def _refresh_selected_fields(chosen: dict[str, _source_v252.Any], diagnostic: dict[str, _source_v252.Any], records: list[dict[str, _source_v252.Any]], selected_record: dict[str, _source_v252.Any], reason: str, median_width_um: float, settings: _source_v252.TraitSettingsV252) -> None:
    groups = _source_v252.v25._candidate_group_members(chosen)
    singleton_points = [group[0] for group in groups if len(group) == 1]
    singleton_ids = [_source_v252.v25._point_stoma_id(point) for point in singleton_points]
    fields = {'trajectory_v25_selected_row_count': int(chosen['k']), 'trajectory_v25_selected_cluster_sizes': [len(group) for group in groups], 'trajectory_v25_selected_singleton_count': len(singleton_points), 'trajectory_v25_selected_singleton_point_indices': singleton_points, 'trajectory_v25_selected_singleton_stoma_ids': singleton_ids, 'trajectory_v25_supported_singleton_count': len(singleton_points), 'trajectory_v25_supported_singleton_stoma_ids': singleton_ids, 'trajectory_v25_ambiguous_singleton_count': 0, 'trajectory_v25_ambiguous_singleton_stoma_ids': [], 'trajectory_v25_row_count_lower_bound': int(chosen['k']), 'trajectory_v25_row_count_upper_bound': int(chosen['k']), 'trajectory_v25_topology_confidence_tier': 'supported_by_v252_general_geometry', 'automatic_row_count': int(chosen['k']), 'automatic_selection_reason': reason, 'row_count_selection_reason': reason, 'audited_row_count_override': False, 'model_confidence': 'moderate', 'trajectory_row_count_min': int(chosen['k']), 'trajectory_row_count_max': int(chosen['k']), 'trajectory_row_count_stable': True, 'trajectory_exact_row_traits_eligible': True, 'trajectory_singleton_validation_required': bool(singleton_points), 'trajectory_singleton_rows_validated': True, 'trajectory_singleton_detector_confidences': [_source_v252.v25._point_confidence(point) for point in singleton_points], 'trajectory_singleton_validation_failure_reason': '', 'trajectory_v252_policy_version': _source_v252.SCRIPT_VERSION}
    chosen.update(fields)
    diagnostic.update(fields)
    diagnostic.update({'global_automatic_row_count': int(chosen['k']), 'row_count_used_for_traits': int(chosen['k']), 'row_count_used_for_traits_source': reason, 'global_row_selection_score': float(selected_record['adjusted_score']), 'global_row_model_confidence': 'moderate', 'candidate_diagnostics': _source_v252.v25._parent_compatible_candidate_diagnostics(records, selected_record, median_width_um, settings), 'trajectory_v25_candidate_diagnostics': _source_v252.v25._top_candidate_diagnostics(records, selected_record)})
    chosen['trajectory_v25_candidate_diagnostics'] = diagnostic['trajectory_v25_candidate_diagnostics']
_source_v252._refresh_selected_fields = _refresh_selected_fields

def _apply_v25_joint_search_v252(parent_chosen: dict[str, _source_v252.Any], parent_candidates: list[dict[str, _source_v252.Any]], diagnostic: dict[str, _source_v252.Any], point_indices: list[int], lateral: _source_v252.np.ndarray, longitudinal: _source_v252.np.ndarray, median_width_um: float, settings: _source_v252.TraitSettingsV252) -> tuple[dict[str, _source_v252.Any], list[dict[str, _source_v252.Any]], dict[str, _source_v252.Any]]:
    chosen, candidates, diagnostic = _source_v252._PARENT_APPLY_V25_JOINT_SEARCH(parent_chosen, parent_candidates, diagnostic, point_indices, lateral, longitudinal, median_width_um, settings)
    records = _source_v252._candidate_records([*candidates, chosen], lateral, longitudinal, median_width_um, settings)
    absorbed: list[dict[str, _source_v252.Any]] = []
    while True:
        edge_singletons = [(point, _source_v252._edge_touch_details(point, settings)) for point in _source_v252.v25._singleton_points(chosen) if _source_v252._edge_touch_details(point, settings)['touches']]
        if not edge_singletons:
            break
        changed = False
        for point, details in edge_singletons:
            revised = _source_v252.v25._absorb_singleton_into_nearest_supported_row(chosen, int(point), lateral, longitudinal)
            if revised is None:
                continue
            revised_record = _source_v252.v25._evaluate_joint_candidate(revised, lateral, longitudinal, median_width_um, settings)
            if not bool(revised_record['valid']):
                continue
            chosen = dict(chosen)
            chosen.update(revised)
            records.append(revised_record)
            absorbed.append({'point_index': int(point), 'stoma_id': _source_v252.v25._point_stoma_id(int(point)), 'edge_touch': details})
            changed = True
        if not changed:
            break
    simplification = None
    if not absorbed:
        simplification = _source_v252._choose_general_simplification(chosen, records, longitudinal, settings)
    if simplification is not None:
        replacement, selected_record, route, geometry = simplification
        chosen = dict(chosen)
        chosen.update(replacement)
        general_fields = {'trajectory_v252_policy_version': _source_v252.SCRIPT_VERSION, 'trajectory_v252_general_row_simplification_applied': True, 'trajectory_v252_general_row_simplification_route': route, 'trajectory_v252_general_row_simplification_score_cost': float(geometry['score_cost']), 'trajectory_v252_general_row_simplification_geometry': geometry}
        chosen.update(general_fields)
        diagnostic.update(general_fields)
        _source_v252._refresh_selected_fields(chosen, diagnostic, records, selected_record, f'v252_{route}', median_width_um, settings)
    remaining = [{'point_index': int(point), 'stoma_id': _source_v252.v25._point_stoma_id(int(point)), 'edge_touch': _source_v252._edge_touch_details(int(point), settings)} for point in _source_v252.v25._singleton_points(chosen) if _source_v252._edge_touch_details(int(point), settings)['touches']]
    edge_fields = {'trajectory_v252_policy_version': _source_v252.SCRIPT_VERSION, 'trajectory_v252_edge_touching_singleton_rule_applied': bool(absorbed or remaining), 'trajectory_v252_edge_touching_singleton_absorbed_count': len(absorbed), 'trajectory_v252_edge_touching_singleton_absorbed': absorbed, 'trajectory_v252_edge_touching_singleton_pending_topology_removal_count': len(remaining), 'trajectory_v252_edge_touching_singleton_pending_topology_removal': remaining, 'trajectory_v252_edge_touch_tolerance_pixels': float(settings.v252_edge_touch_tolerance_pixels)}
    chosen.update(edge_fields)
    diagnostic.update(edge_fields)
    if absorbed:
        selected_record = _source_v252.v25._evaluate_joint_candidate(chosen, lateral, longitudinal, median_width_um, settings)
        records.append(selected_record)
        _source_v252._refresh_selected_fields(chosen, diagnostic, records, selected_record, 'v252_edge_touching_singleton_absorbed_into_supported_row', median_width_um, settings)
        chosen.update(edge_fields)
        diagnostic.update(edge_fields)
    best_by_k: dict[int, dict[str, _source_v252.Any]] = {int(candidate['k']): candidate for candidate in candidates}
    best_by_k[int(chosen['k'])] = chosen
    return (chosen, [best_by_k[key] for key in sorted(best_by_k)], diagnostic)
_source_v252._apply_v25_joint_search_v252 = _apply_v25_joint_search_v252

def _v25_partition_candidate_v252(band: dict[str, _source_v252.Any], linked: list[dict[str, _source_v252.Any]], cut: int, gaps: list[float], boundary_evidence_by_rows: dict[tuple[str, str, str], dict[str, _source_v252.Any]], median_width_um: float, settings: _source_v252.TraitSettingsV252) -> dict[str, _source_v252.Any]:
    result = _source_v252._PARENT_PARTITION_CANDIDATE(band, linked, cut, gaps, boundary_evidence_by_rows, median_width_um, settings)
    if bool(result.get('accepted')):
        return result
    failures = set((str(value) for value in result.get('failed_gates', [])))
    rows_resolved_by_general_rule = bool(linked and all((bool(row.get('trajectory_v252_general_row_simplification_applied')) for row in linked)))
    topology_only = bool(failures == {'row_topology_not_supported'} and rows_resolved_by_general_rule)
    relaxed_multipoint_gap = bool(failures == {'gap_width'} and bool(result.get('isolated_one_row_side')) and (min(int(result.get('left_stomata') or 0), int(result.get('right_stomata') or 0)) >= int(settings.v252_multipoint_boundary_min_stomata_per_side)) and (float(result.get('gap_factor') or 0.0) >= float(settings.v252_multipoint_boundary_min_gap_width_factor)) and (float(result.get('gap_ratio') or 0.0) >= float(settings.v252_multipoint_boundary_min_local_gap_ratio)) and bool(result.get('image_support_identity_exact')) and (result.get('image_support') is not None) and (float(result['image_support']) >= float(settings.v252_multipoint_boundary_min_image_support_ratio)) and (float(result.get('stability') or 0.0) >= float(settings.v252_multipoint_boundary_min_stability_fraction)) and (not bool(result.get('nonlinear_row_topology'))))
    if not (topology_only or relaxed_multipoint_gap):
        return result
    result.update({'accepted': True, 'failed_gates_before_v252_general_rule': sorted(failures), 'failed_gates': [], 'trajectory_v252_general_band_boundary_applied': True, 'trajectory_v252_general_band_boundary_route': 'resolved_row_topology_all_other_v25_gates_passed' if topology_only else 'strong_exact_image_supported_multipoint_gap', 'decision_route': 'v252_resolved_row_topology' if topology_only else 'v252_strong_exact_image_supported_multipoint_gap'})
    return result
_source_v252._v25_partition_candidate_v252 = _v25_partition_candidate_v252

def _remaining_edge_singleton_rows(rows: list[dict[str, _source_v252.Any]], settings: _source_v252.TraitSettingsV252) -> list[tuple[dict[str, _source_v252.Any], int, dict[str, _source_v252.Any]]]:
    result: list[tuple[dict[str, _source_v252.Any], int, dict[str, _source_v252.Any]]] = []
    for row in rows:
        members = [int(value) for value in row.get('_point_indices', [])]
        if len(members) != 1:
            continue
        details = _source_v252._edge_touch_details(members[0], settings)
        if details['touches']:
            result.append((row, members[0], details))
    return result
_source_v252._remaining_edge_singleton_rows = _remaining_edge_singleton_rows

def _remove_unabsorbed_edge_singletons_from_topology(rows: list[dict[str, _source_v252.Any]], bands: list[dict[str, _source_v252.Any]], assignments: dict[int, dict[str, _source_v252.Any]], stoma_traits: list[dict[str, _source_v252.Any]], audit: dict[str, _source_v252.Any], settings: _source_v252.TraitSettingsV252) -> tuple[list[dict[str, _source_v252.Any]], list[dict[str, _source_v252.Any]], dict[int, dict[str, _source_v252.Any]], dict[str, _source_v252.Any]]:
    candidates = _source_v252._remaining_edge_singleton_rows(rows, settings)
    if not candidates:
        audit['trajectory_v252_edge_touching_singleton_removed_from_topology_count'] = 0
        audit['trajectory_v252_edge_touching_singleton_removed_from_topology'] = []
        return (rows, bands, assignments, audit)
    removed_ids = {str(row['row_id']) for row, _, _ in candidates}
    removed_records: list[dict[str, _source_v252.Any]] = []
    for row, point_index, details in candidates:
        row_id = str(row['row_id'])
        former_band = str(row.get('band_id') or '')
        marker = {'trajectory_v252_policy_version': _source_v252.SCRIPT_VERSION, 'trajectory_v252_edge_touching_singleton_ignored_for_row_delimitation': True, 'trajectory_v252_edge_touching_singleton_edge_sides': details['sides'], 'trajectory_v252_edge_touch_tolerance_pixels': float(settings.v252_edge_touch_tolerance_pixels), 'trajectory_v252_topology_exclusion_reason': 'singleton_detector_box_touches_image_edge', 'row_id': '', 'band_id': '', 'row_band_spatial_eligible': False, 'row_complete_topology_eligible': False, 'row_structure_eligible': False, 'row_band_spatial_exclusion_reason': 'singleton_detector_box_touches_image_edge'}
        assignments[int(point_index)].update(marker)
        stoma_traits[int(point_index)].update(marker)
        removed_records.append({'stoma_id': str(stoma_traits[int(point_index)].get('stoma_id') or ''), 'former_row_id': row_id, 'former_band_id': former_band, 'edge_sides': details['sides']})
    rows = [row for row in rows if str(row['row_id']) not in removed_ids]
    row_lookup = {str(row['row_id']): row for row in rows}
    lower_before = _source_v252.base.optional_int(audit.get('detected_row_count_v25_lower_bound'))
    upper_before = _source_v252.base.optional_int(audit.get('detected_row_count_v25_upper_bound'))
    median_widths = [_source_v252.base.optional_float(record.get('prediction_width_um')) for record in stoma_traits]
    median_widths = [value for value in median_widths if value is not None and value > 0]
    median_width_um = float(_source_v252.np.median(_source_v252.np.asarray(median_widths, dtype=float))) if median_widths else 1.0
    rebuilt_bands: list[dict[str, _source_v252.Any]] = []
    for band in bands:
        linked = [row_lookup[str(row_id)] for row_id in band.get('row_ids', []) if str(row_id) in row_lookup]
        if not linked:
            continue
        rebuilt_bands.append(_source_v252.v24._rebuild_band_v24(band, linked, stoma_traits, median_width_um, None, 1, {'trajectory_v252_edge_touching_singleton_removed_from_band': True, 'trajectory_v252_policy_version': _source_v252.SCRIPT_VERSION}))
    rows, rebuilt_bands, assignments = _source_v252.v24._renumber_final_bands(rows, rebuilt_bands, assignments)
    parent_edge_audit = audit.get('band_spatial_eligibility') if isinstance(audit.get('band_spatial_eligibility'), list) else []
    edge_audit = _source_v252.v25._apply_v25_standardized_multirow_edge_rule(rows, rebuilt_bands, assignments, stoma_traits, settings, parent_edge_audit)
