def _visibility_details(point_index: int, stoma_traits: list[dict[str, _source_v253.Any]], settings: _source_v253.TraitSettingsV253) -> dict[str, _source_v253.Any]:
    """Assess full detector-box visibility using explicit records and metadata."""
    metadata = _source_v253.v14._ACTIVE_IMAGE_METADATA or {}
    record = stoma_traits[int(point_index)] if 0 <= int(point_index) < len(stoma_traits) else None
    width = _source_v253.base.optional_float(metadata.get('image_width'))
    height = _source_v253.base.optional_float(metadata.get('image_height'))
    x1 = _source_v253.base.optional_float(record.get('prediction_x1_pixels')) if record else None
    y1 = _source_v253.base.optional_float(record.get('prediction_y1_pixels')) if record else None
    x2 = _source_v253.base.optional_float(record.get('prediction_x2_pixels')) if record else None
    y2 = _source_v253.base.optional_float(record.get('prediction_y2_pixels')) if record else None
    values = (width, height, x1, y1, x2, y2)
    assessable = bool(all((value is not None and _source_v253.math.isfinite(float(value)) for value in values)) and float(width) > 0.0 and (float(height) > 0.0) and (float(x1) <= float(x2)) and (float(y1) <= float(y2)))
