    if assessable:
        tolerance = float(settings.v253_singleton_full_visibility_tolerance_pixels)
        if float(x1) <= tolerance:
            sides.append('left')
        if float(x2) >= float(width) - tolerance:
            sides.append('right')
        if float(y1) <= tolerance:
            sides.append('top')
        if float(y2) >= float(height) - tolerance:
            sides.append('bottom')
    clipped = bool(assessable and sides)
    fully_visible = bool(assessable and (not sides))
    return {'assessable': assessable, 'fully_visible': fully_visible, 'clipped': clipped, 'visibility_status': 'fully_visible' if fully_visible else 'detector_box_touches_image_edge' if clipped else 'full_visibility_unassessable', 'sides': sides, 'tolerance_pixels': float(settings.v253_singleton_full_visibility_tolerance_pixels), 'prediction_x1_pixels': x1, 'prediction_y1_pixels': y1, 'prediction_x2_pixels': x2, 'prediction_y2_pixels': y2, 'image_width_pixels': width, 'image_height_pixels': height}
