def _choose_v253_additional_simplification(chosen: dict[str, _source_v253.Any], records: list[dict[str, _source_v253.Any]], longitudinal: _source_v253.np.ndarray, settings: _source_v253.TraitSettingsV253) -> tuple[dict[str, _source_v253.Any], dict[str, _source_v253.Any], str, dict[str, _source_v253.Any]] | None:
    selected_record = _source_v253._selected_record(chosen, records)
