    alternatives = [record for record in records if bool(record.get('valid')) and int(record['candidate_row_count']) == selected_k - 1 and (int(record.get('singleton_row_count') or 0) == 0)]
    if selected_k < 2 or not alternatives:
        return None
    simpler_record = min(alternatives, key=lambda record: (float(record['adjusted_score']), abs(float(record['slope_angle_deg']))))
    score_cost = float(simpler_record['adjusted_score']) - float(selected_record['adjusted_score'])
