    failures = {str(value) for value in result.get('failed_gates', [])}
    topology_only = failures == {'row_topology_not_supported'}
    rows_resolved_by_v253 = bool(linked and all((bool(row.get('trajectory_v253_general_row_simplification_applied')) for row in linked)))
    resolved_exact_support = bool(result.get('image_support_identity_exact') and result.get('image_support') is not None and (float(result['image_support']) >= float(settings.v253_resolved_boundary_min_image_support_ratio)))
