    resolved_by_v253 = bool(rows_resolved_by_v253 and (topology_only or resolved_near_threshold_isolated_boundary))
    exact_support = bool(result.get('image_support_identity_exact') and result.get('image_support') is not None and (float(result['image_support']) >= float(settings.v253_ambiguous_boundary_min_image_support_ratio)))
    topology_stability_supported = bool(linked and all((_source_v253.base.optional_float(row.get('trajectory_v25_row_count_stability_fraction')) is not None and float(row['trajectory_v25_row_count_stability_fraction']) >= float(settings.v253_ambiguous_boundary_min_row_count_stability) and (_source_v253.base.optional_float(row.get('trajectory_v25_assignment_stability_fraction')) is not None) and (float(row['trajectory_v25_assignment_stability_fraction']) >= float(settings.v253_ambiguous_boundary_min_assignment_stability)) and (_source_v253.base.optional_int(row.get('trajectory_v25_row_count_lower_bound')) == _source_v253.base.optional_int(row.get('trajectory_v25_selected_row_count')) == _source_v253.base.optional_int(row.get('trajectory_v25_row_count_upper_bound'))) for row in linked)))
    strong_ambiguous_boundary = bool(topology_only and (not bool(result.get('isolated_one_row_side'))) and (float(result.get('gap_factor') or 0.0) >= float(settings.v253_ambiguous_boundary_min_gap_width_factor)) and (float(result.get('gap_ratio') or 0.0) >= float(settings.v253_ambiguous_boundary_min_local_gap_ratio)) and (float(result.get('stability') or 0.0) >= float(settings.v253_ambiguous_boundary_min_stability_fraction)) and (min(int(result.get('left_stomata') or 0), int(result.get('right_stomata') or 0)) >= int(settings.v253_ambiguous_boundary_min_stomata_per_side)) and exact_support and topology_stability_supported and (not bool(result.get('nonlinear_row_topology'))))
    if not (resolved_by_v253 or strong_ambiguous_boundary):
        return result
    route = 'resolved_v253_row_topology_near_threshold_exact_image_boundary' if resolved_near_threshold_isolated_boundary else 'resolved_v253_row_topology_all_other_v25_gates_passed' if resolved_by_v253 else 'strong_exact_image_supported_ambiguous_topology_boundary'
