def _update_v254_output_provenance(output_dir: _source_v254.Path) -> None:
    provenance_path = output_dir / 'trait_extraction_provenance.json'
    if provenance_path.is_file():
        provenance = _source_v254.json.loads(provenance_path.read_text(encoding='utf-8'))
        provenance.update({'script_version': _source_v254.SCRIPT_VERSION, 'v254_parent_script': str(_source_v254._PARENT_V253_SCRIPT_PATH), 'v254_parent_script_sha256': _source_v254.hashlib.sha256(_source_v254._PARENT_V253_SCRIPT_PATH.read_bytes()).hexdigest(), 'v254_contains_image_specific_rules': False, 'v254_contains_manual_row_count_overrides': False, 'v254_policy': 'guarded exact-image-supported dominant multipoint gaps, supported near-threshold multipoint gaps, and balanced evidence-based over-capacity partitioning', 'v254_development_status': 'rules derived from two audited 40-image sets; validation on a third untouched balanced set is required before lock'})
        provenance_path.write_text(_source_v254.json.dumps(_source_v254.base.json_safe(provenance), indent=2, sort_keys=True) + '\n', encoding='utf-8')
    report_path = output_dir / 'TRAIT_EXTRACTION_REPORT.txt'
    if report_path.is_file():
        report = report_path.read_text(encoding='utf-8').rstrip()
        addition = '\nV2.5.4 is a separate band-boundary successor to v2.5.3.\nIt uses no image name, stomatal identifier, row identifier, fixed membership or manual row count. Density, morphometry, row assignment and the v2.5.3 fully-visible-singleton rule are unchanged.\nV2.5.4 requires validation on a third untouched balanced set.\n'
        if 'V2.5.4 is a separate band-boundary successor' not in report:
            report += addition
        report_path.write_text(report, encoding='utf-8')
_source_v254._update_v254_output_provenance = _update_v254_output_provenance

